SELECT 'tourapi-2900328', '강수사', '서대문구', 37.5713634885, 126.9342059353, '서울특별시 서대문구 연희로 157 (연희동)', '39', '강수사는 서울시 서대문구 연희동, 외국인학교 맞은편에 있는 일식 전문점이다. 두툼하게 썰린 숙성회와 다양한 초밥, 튀김, 탕 메뉴가 준비되어 있으며, 런치 코스와 도시락 메뉴도 합리적인 가격으로 제공한다. 단체석이 있어서 모임하기 좋다. 1km 안에 궁동근린공원, 자연공원, 쇼핑센터 등의 관광지가 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/18/2900318_image2_1.jpg', '', 'TOURAPI', '2900328', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희로 157 (연희동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2900328","contenttypeid":"39","createdtime":"20221107153531","firstimage":"https://tong.visitkorea.or.kr/cms/resource/18/2900318_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/18/2900318_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9342059353","mapy":"37.5713634885","mlevel":"6","modifiedtime":"20261102165330","sigungucode":"","tel":"","title":"강수사","zipcode":"03699","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020200","detail":{"contentid":"2900328","contenttypeid":"39","title":"강수사","createdtime":"20221107153531","modifiedtime":"20261102165330","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/18/2900318_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/18/2900318_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020200","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연희로 157 (연희동)","addr2":"","zipcode":"03699","mapx":"126.9342059353","mapy":"37.5713634885","mlevel":"6","overview":"강수사는 서울시 서대문구 연희동, 외국인학교 맞은편에 있는 일식 전문점이다. 두툼하게 썰린 숙성회와 다양한 초밥, 튀김, 탕 메뉴가 준비되어 있으며, 런치 코스와 도시락 메뉴도 합리적인 가격으로 제공한다. 단체석이 있어서 모임하기 좋다. 1km 안에 궁동근린공원, 자연공원, 쇼핑센터 등의 관광지가 있다."}}}'
