SELECT 'tourapi-2900309', '고미정', '서대문구', 37.5727056039, 126.9370248936, '서울특별시 서대문구 연희로26길 28 (연희동)', '39', '서대문구 연희동에 있는 한식 전문점이다. 연세대학교 북문 아래쪽에 있으며, 건물 2층과 3층을 사용하는 식당이다. 이천쌀밥정식, 고사리소불고기정식, 간장게장정식 등 정갈한 한식 메뉴를 제공한다. 특히 간장게장은 적당히 달달하고 깊은 맛이 일품이며, 제육볶음은 고기가 두툼하고 맵지도 않으면서 돼지불백 느낌이 나는 인기 메뉴다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/06/2900306_image2_1.jpg', '', 'TOURAPI', '2900309', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희로26길 28 (연희동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2900309","contenttypeid":"39","createdtime":"20221107153051","firstimage":"https://tong.visitkorea.or.kr/cms/resource/06/2900306_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/06/2900306_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9370248936","mapy":"37.5727056039","mlevel":"6","modifiedtime":"20261103152414","sigungucode":"","tel":"","title":"고미정","zipcode":"03723","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","detail":{"contentid":"2900309","contenttypeid":"39","title":"고미정","createdtime":"20221107153051","modifiedtime":"20261103152414","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/06/2900306_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/06/2900306_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRe