SELECT 'tourapi-2453179', '고촌이종근기념관', '서대문구', 37.5597464264, 126.9631392793, '서울특별시 서대문구 충정로 8', '12', '고촌이종근기념관은 종근당 창업자인 고촌 이종근 회장의 철학과 업적을 기리고, 실패를 두려워하지 않는 도전의 자세와 검소한 삶 속에서도 어려운 이웃과 함께했던 나눔의 정신을 남기고자 마련된 종근당 창업 전시관이다. 또한 고촌이종근기념관은 국내외 의약사를 함께 관람할 수 있는 제약박물관이기도 하다. 고촌 이종근 회장의 일생과 종근당의 발전 과정, 국내외 의약사의 흐름을 이해할 수 있는 제1전시실과 고촌의 도전과 나눔의 정신 등을 직접 체험해 볼 수 있는 체험관 형식의 제2전시실로 구성되어 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'http://tong.visitkorea.or.kr/cms/resource/45/3462945_image2_1.jpg', '', 'TOURAPI', '2453179', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 충정로 8","addr2":"","areacode":"1","cat1":"A02","cat2":"A0204","cat3":"A02040800","contentid":"2453179","contenttypeid":"12","createdtime":"20161213013619","firstimage":"http://tong.visitkorea.or.kr/cms/resource/45/3462945_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/45/3462945_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9631392793","mapy":"37.5597464264","mlevel":"6","modifiedtime":"20250402164948","sigungucode":"14","tel":"","title":"고촌이종근기념관","zipcode":"03742","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"EX","lclsSystm2":"EX06","lclsSystm3":"EX061000","detail":{"contentid":"2453179","contenttypeid":"12","title":"고촌이종근기념관","createdtime":"20161213013619","modifiedtime":"20250402164948","tel":"","telname":"","homepage":"<a href=\"https://www.kochonhall.or.kr/\" target=\"_blank\" title=\"새창 : 고촌홀 홈페이지로 이동\">https://www.kochonhall.or.kr/</a>","firstimage":"http://tong.visitkorea.or.kr/cms/resource/45/3462945_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/45/3462945_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"1","sigungucode":"14","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"EX","lclsSystm2":"EX06","lclsSystm3":"EX061000","cat1":"A02","cat2":"A0204","cat3":"A02040800","addr1":"서울특별시 서대문구 충정로 8","addr2":"","zipcode":"03742","mapx":"126.9631392793","mapy":"37.5597464264","mlevel":"6","overview":"고촌이종근기념관은 종근당 창업자인 고촌 이종근 회장의 철학과 업적을 기리고, 실패를 두려워하지 않는 도전의 자세와 검소한 삶 속에서도 어려운 이웃과 함께했던 나눔의 정신을 남기고자 마련된 종근당 창업 전시관이다.\n또한 고촌이종근기념관은 국내외 의약사를 함께 관람할 수 있는 제약박물관이기도 하다. 고촌 이종근 회장의 일생과 종근당의 발전 과정, 국내외 의약사의 흐름을 이해할 수 있는 제1전시실과 고촌의 도전과 나눔의 정신 등을 직접 체험해 볼 수 있는 체험관 형식의 제2전시실로 구성되어 있다."}}}'
