SELECT 'tourapi-4013035', '교보문고 이화여대 교내서점', '서대문구', 37.5644645178259, 126.950288837762, '서울특별시 서대문구 이화여대길 52 (대현동) B4층', '38', '교보문고는 ''사람은 책을 만들고 책은 사람을 만든다''는 철학 아래 고객의 지적 성장과 정서적 휴식을 돕는 대한민국 대표 서점입니다. 방대한 도서 큐레이션과 다채로운 문화 공간을 통해 책과 사람이 연결되는 풍요로운 경험을 선사합니다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/94/4043694_image2_1.png', '', 'TOURAPI', '4013035', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 이화여대길 52 (대현동)","addr2":"B4층","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"4013035","contenttypeid":"38","createdtime":"20260207122203","firstimage":"https://tong.visitkorea.or.kr/cms/resource/94/4043694_image2_1.png","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/94/4043694_image3_1.png","cpyrhtDivCd":"Type3","mapx":"126.950288837762","mapy":"37.5644645178259","mlevel":"","modifiedtime":"20260327092150","sigungucode":"","tel":"","title":"교보문고 이화여대 교내서점","zipcode":"03760","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH04","lclsSystm3":"SH040300","detail":{"contentid":"4013035","contenttypeid":"38","title":"교보문고 이화여대 교내서점","createdtime":"20260207122203","modifiedtime":"20260327092150","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/94/4043694_image2_1.png","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/94/4043694_image3_1.png","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH04","lclsSystm3":"SH040300","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 이화여대길 52 (대현동)","addr2":"B4층","zipcode":"03760","mapx":"126.950288837762","mapy":"37.5644645178259","mlevel":"","overview":"교보문고는 ''사람은 책을 만들고 책은 사람을 만든다''는 철학 아래 고객의 지적 성장과 정서적 휴식을 돕는 대한민국 대표 서점입니다. 방대한 도서 큐레이션과 다채로운 문화 공간을 통해 책과 사람이 연결되는 풍요로운 경험을 선사합니다."}}}'
