SELECT 'tourapi-2813170', '국립대한민국임시정부기념관', '서대문구', 37.5760930847, 126.9544351508, '서울특별시 서대문구 통일로 279-24', '14', '국립대한민국임시정부기념관은 3.1운동으로 건립된 대한민국 임시정부의 법통을 계승한다고 밝히는 헌법정신의 내용과 가치를 널리 알리는 공간이다. 기념관에서는 대한민국 임시정부의 역사를 주제별로 펼쳐 알리는 상설전시와 1년에 두 차례 특별주제를 다루는 특별기획전시가 열린다. 또한 자라나는 미래세대가 대한민국 임시정부를 기억하고 그 역사를 자랑스럽게 여길 수 있도록 청소년을 대상으로 창의적인 체험 프로그램도 운영하고 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/29/4095029_image2_1.jpg', '', 'TOURAPI', '2813170', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 통일로 279-24","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2813170","contenttypeid":"14","createdtime":"20220325112726","firstimage":"https://tong.visitkorea.or.kr/cms/resource/29/4095029_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/29/4095029_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9544351508","mapy":"37.5760930847","mlevel":"6","modifiedtime":"20260731132554","sigungucode":"","tel":"","title":"국립대한민국임시정부기념관","zipcode":"03732","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE07","lclsSystm3":"VE070200","detail":{"contentid":"2813170","contenttypeid":"14","title":"국립대한민국임시정부기념관","createdtime":"20220325112726","modifiedtime":"20260731132554","tel":"","telname":"","homepage":"https://www.nmkpg.go.kr","firstimage":"https://tong.visitkorea.or.kr/cms/resource/29/4095029_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/29/4095029_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE07","lclsSystm3":"VE070200","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 통일로 279-24","addr2":"","zipcode":"03732","mapx":"126.9544351508","mapy":"37.5760930847","mlevel":"6","overview":"국립대한민국임시정부기념관은 3.1운동으로 건립된 대한민국 임시정부의 법통을 계승한다고 밝히는 헌법정신의 내용과 가치를 널리 알리는 공간이다. 기념관에서는 대한민국 임시정부의 역사를 주제별로 펼쳐 알리는 상설전시와 1년에 두 차례 특별주제를 다루는 특별기획전시가 열린다. 또한 자라나는 미래세대가 대한민국 임시정부를 기억하고 그 역사를 자랑스럽게 여길 수 있도록 청소년을 대상으로 창의적인 체험 프로그램도 운영하고 있다."}}}'
