SELECT 'tourapi-4025562', '그랜드세이코 세이코 현대백화점 신촌점', '서대문구', 37.5560830579515, 126.935844876509, '서울특별시 서대문구 신촌로 83 (창천동) 2층', '38', '그랜드세이코(Grand Seiko)는 일본의 시계 제조 기술력이 집약된 하이엔드 럭셔리 워치 브랜드입니다. 독보적인 정확도의 무브먼트와 장인의 정교한 피니싱을 통해 시계 본연의 기능과 미적 완성도의 정점을 보여줍니다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/41/4045641_image2_1.jpg', '', 'TOURAPI', '4025562', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 신촌로 83 (창천동)","addr2":"2층","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"4025562","contenttypeid":"38","createdtime":"20260227100032","firstimage":"https://tong.visitkorea.or.kr/cms/resource/41/4045641_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/41/4045641_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.935844876509","mapy":"37.5560830579515","mlevel":"","modifiedtime":"20260330091611","sigungucode":"","tel":"","title":"그랜드세이코 세이코 현대백화점 신촌점","zipcode":"03789","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH04","lclsSystm3":"SH040300","detail":{"contentid":"4025562","contenttypeid":"38","title":"그랜드세이코 세이코 현대백화점 신촌점","createdtime":"20260227100032","modifiedtime":"20260330091611","tel":"","telname":"","homepage":"www.seikowatches.com","firstimage":"https://tong.visitkorea.or.kr/cms/resource/41/4045641_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/41/4045641_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigung