INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-3078407', '금호아트홀 연세', '서대문구', 37.563137, 126.936601, '서울특별시 서대문구 연세로 50 (신촌동)', '14', '금호아트홀 연세는 연세대학교 백양로에 위치한 실내악 전용 공연장이다. 금호아시아나그룹이 문화예술 진흥을 위해 100억 원을 기부한 데서 시작되어 2014년 8월 착공, 약 1년여간의 공사 기간을 거쳐 2015년 10월 완공되었다. 한층 업그레이드된 연주와 음향, 관람 시설을 바탕으로 광화문 금호아트홀에서 진행했던 금호영재, 영아티스트, 영체임버콘서트 시리즈, 아름다운 목요일 콘서트 시리즈 등의 공연을 금호아트홀 연세의 무대로 옮겨 역사를 이어간다. 한국 클래식 음악계를 풍성하게 할 무대와 지원 사업들을 계속해서 이어 나가며 클래식에 관심 있는 청중들에게 다가가고 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/41/3082441_image2_1.JPG', '', 'TOURAPI', '3078407', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연세로 50 (신촌동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"3078407","contenttypeid":"14","createdtime":"20231204144850","firstimage":"https://tong.visitkorea.or.kr/cms/resource/41/3082441_image2_1.JPG","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/41/3082441_image3_1.JPG","cpyrhtDivCd":"Type3","mapx":"126.936601","mapy":"37.563137","mlevel":"6","modifiedtime":"20260401130142","sigungucode":"","tel":"","title":"금호아트홀 연세","zipcode":"03722","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE06","lclsSystm3":"VE060100","detail":{"contentid":"3078407","contenttypeid":"14","title":"금호아트홀 연세","createdtime":"20231204144850","modifiedtime":"20260401130142","tel":"","telname":"","homepage":"https://www.kumhoarthall.com:448/","firstimage":"https://tong.visitkorea.or.kr/cms/resource/41/3082441_image2_1.JPG","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/41/3082441_image3_1.JPG","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE06","lclsSystm3":"VE060100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연세로 50 (신촌동)","addr2":"","zipcode":"03722","mapx":"126.936601","mapy":"37.563137","mlevel":"6","overview":"금호아트홀 연세는 연세대학교 백양로에 위치한 실내악 전용 공연장이다. 금호아시아나그룹이 문화예술 진흥을 위해 100억 원을 기부한 데서 시작되어 2014년 8월 착공, 약 1년여간의 공사 기간을 거쳐 2015년 10월 완공되었다. 한층 업그레이드된 연주와 음향, 관람 시설을 바탕으로 광화문 금호아트홀에서 진행했던 금호영재, 영아티스트, 영체임버콘서트 시리즈, 아름다운 목요일 콘서트 시리즈 등의 공연을 금호아트홀 연세의 무대로 옮겨 역사를 이어간다. 한국 클래식 음악계를 풍성하게 할 무대와 지원 사업들을 계속해서 이어 나가며 클래식에 관심 있는 청중들에게 다가가고 있다."}}}'
