SELECT 'tourapi-2918773', '김삼보김치찌개', '서대문구', 37.5589304821, 126.939600458, '서울특별시 서대문구 명물길 62 오시리스타워 1층', '39', '서대문구 창천동에 위치한 김삼보김치찌개는 가마솥 밥과 김치찌개를 전문으로 선보이는 식당이다. 합리적인 가격에 푸짐한 양을 제공해 학생과 직장인 등 다양한 방문객의 발길이 이어진다. 대표 메뉴인 김치찌개는 깊고 진한 국물 맛이 특징이며, 갓 지은 따뜻한 가마솥 밥과 함께 즐길 수 있어 든든한 한 끼 식사로 제격이다. 넓고 편안한 실내 공간을 갖추고 있어 혼밥은 물론 친구, 가족, 동료와 함께 방문하기에도 좋다. 특히 점심시간에는 식사를 즐기려는 손님들로 붐비며, 꾸준히 찾는 단골이 많아 오랜 시간 사랑받고 있다. 푸짐한 양과 안정적인 맛, 뛰어난 가성비를 갖춘 곳으로 신촌 일대에서 식사 장소를 찾는 이들에게 꾸준히 추천되는 맛집이다.', 'https://www.data.go.kr/data/15101578/openapi.do', NULL, '', 'TOURAPI', '2918773', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 명물길 62 오시리스타워","addr2":"1층","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2918773","contenttypeid":"39","createdtime":"20221124180318","firstimage":"","firstimage2":"","cpyrhtDivCd":"","mapx":"126.9396004580","mapy":"37.5589304821","mlevel":"6","modifiedtime":"20260605094158","sigungucode":"","tel":"","title":"김삼보김치찌개","zipcode":"03777","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","detail":{"contentid":"2918773","contenttypeid":"39","title":"김삼보김치찌개","createdtime":"20221124180318","modifiedtime":"20260605094158","tel":"","telname":"","homepage":"","firstimage":"","firstimage2":"","cpyrhtDivCd":"","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 명물길 62 오시리스타워","addr2":"1층","zipcode":"03777","mapx":"126.9396004580","mapy":"37.5589304821","mlevel":"6","overview":"서대문구 창천동에 위치한 김삼보김치찌개는 가마솥 밥과 김치찌개를 전문으로 선보이는 식당이다. 합리적인 가격에 푸짐한 양을 제공해 학생과 직장인 등 다양한 방문객의 발길이 이어진다. 대표 메뉴인 김치찌개는 깊고 진한 국물 맛이 특징이며, 갓 지은 따뜻한 가마솥 밥과 함께 즐길 수 있어 든든한 한 끼 식사로 제격이다. 넓고 편안한 실내 공간을 갖추고 있어 혼밥은 물론 친구, 가족, 동료와 함께 방문하기에도 좋다. 특히 점심시간에는 식사를 즐기려는 손님들로 붐비며, 꾸준히 찾는 단골이 많아 오랜 시간 사랑받고 있다. 푸짐한 양과 안정적인 맛, 뛰어난 가성비를 갖춘 곳으로 신촌 일대에서 식사 장소를 찾는 이들에게 꾸준히 추천되는 맛집이다."}}}'
