SELECT 'tourapi-2900286', '녹원쌈밥 연희점', '서대문구', 37.5724818091, 126.9341439887, '서울특별시 서대문구 연희로25길 22 (연희동)', '39', '서울 연희동에 위치한 녹원쌈밥은 쌈밥정식과 보쌈정식을 대표 메뉴로 하는 음식점이다. 신선한 쌈채소와 함께 매콤한 제육볶음, 오징어볶음, 수육을 즐길 수 있다. 사이드 메뉴로는 직접 뽑은 순메밀 함유량 80%의 메밀전과 막국수도 인기가 많으며, 특히 여름철에는 시원한 막국수를 찾는 손님이 많다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/82/2900282_image2_1.jpg', '', 'TOURAPI', '2900286', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희로25길 22 (연희동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2900286","contenttypeid":"39","createdtime":"20221107152544","firstimage":"https://tong.visitkorea.or.kr/cms/resource/82/2900282_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/82/2900282_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9341439887","mapy":"37.5724818091","mlevel":"6","modifiedtime":"20260702141324","sigungucode":"","tel":"","title":"녹원쌈밥 연희점","zipcode":"03697","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","detail":{"contentid":"2900286","contenttypeid":"39","title":"녹원쌈밥 연희점","createdtime":"20221107152544","modifiedtime":"20260702141324","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/82/2900282_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/82/2900282_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnC