SELECT 'tourapi-2873449', '닭내장집', '서대문구', 37.5694565436, 126.915616388, '서울특별시 서대문구 수색로 28-5', '39', '닭내장집은 서대문구 남가좌동 모래내시장에 위치한 닭내장 전문점으로 오래된 노포의 느낌이 물씬 풍기는 곳이다. 닭내장이 메인 메뉴이나 입구에서 철판 가득 보글보글 끓여지는 닭발 또한 보기만 해도 군침이 도는 비주얼이다. 닭내장을 다 먹은 후 볶아 먹는 볶음밥도 별미이다. 저녁 술안주뿐만 아니라 닭내장 백반으로 점심 메뉴가 있어 점심에도 찾는 이들이 많다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/33/3576333_image2_1.jpg', '', 'TOURAPI', '2873449', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 수색로 28-5","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2873449","contenttypeid":"39","createdtime":"20221024151811","firstimage":"https://tong.visitkorea.or.kr/cms/resource/33/3576333_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/33/3576333_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9156163880","mapy":"37.5694565436","mlevel":"6","modifiedtime":"20260803163358","sigungucode":"","tel":"","title":"닭내장집","zipcode":"03712","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","detail":{"contentid":"2873449","contenttypeid":"39","title":"닭내장집","createdtime":"20221024151811","modifiedtime":"20260803163358","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/33/3576333_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/33/3576333_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDo