SELECT 'tourapi-3456362', '대현문화공원', '서대문구', 37.5576991161, 126.9449298864, '서울특별시 서대문구 이화여대1길 10 (대현동)', '12', '서울에 있는 대현문화공원은 서울특별시 서대문구 대현동에 위치한 공원이다. 이 공원은 지역 주민들에게 자연과 여가 공간을 제공하며, 주변 도심 속에서 휴식을 취할 수 있는 장소로 사랑받고 있다. 대현문화공원은 다양한 산책로와 조경이 잘 어우러진 녹지 공간을 갖추고 있으며, 지역 주민들의 건강과 여가 활동을 지원하기 위한 운동기구와 휴식 공간이 마련되어 있다. 특히, 근린공원이라는 특성상 지역 주민들이 자주 찾는 친근한 장소로 알려져 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'http://tong.visitkorea.or.kr/cms/resource/80/3456380_image2_1.jpg', '', 'TOURAPI', '3456362', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 이화여대1길 10 (대현동)","addr2":"","areacode":"1","cat1":"A02","cat2":"A0202","cat3":"A02020700","contentid":"3456362","contenttypeid":"12","createdtime":"20241220165817","firstimage":"http://tong.visitkorea.or.kr/cms/resource/80/3456380_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/80/3456380_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9449298864","mapy":"37.5576991161","mlevel":"6","modifiedtime":"20250730161058","sigungucode":"14","tel":"","title":"대현문화공원","zipcode":"03766","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE03","lclsSystm3":"VE030400","detail":{"contentid":"3456362","contenttypeid":"12","title":"대현문화공원","createdtime":"20241220165817","modifiedtime":"20250730161058","tel":"","telname":"","homepage":"","firstimage":"http://tong.visitkorea.or.kr/cms/resource/80/3456380_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/80/3456380_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"1","sigungucode":"14","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE03","lclsSystm3":"VE030400","cat1":"A02","cat2":"A0202","cat3":"A02020700","addr1":"서울특별시 서대문구 이화여대1길 10 (대현동)","addr2":"","zipcode":"03766","mapx":"126.9449298864","mapy":"37.5576991161","mlevel":"6","overview":"서울에 있는 대현문화공원은 서울특별시 서대문구 대현동에 위치한 공원이다. 이 공원은 지역 주민들에게 자연과 여가 공간을 제공하며, 주변 도심 속에서 휴식을 취할 수 있는 장소로 사랑받고 있다.\n<br />대현문화공원은 다양한 산책로와 조경이 잘 어우러진 녹지 공간을 갖추고 있으며, 지역 주민들의 건강과 여가 활동을 지원하기 위한 운동기구와 휴식 공간이 마련되어 있다. <br />특히, 근린공원이라는 특성상 지역 주민들이 자주 찾는 친근한 장소로 알려져 있다."}}}'
