INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-1828571', '독립관', '서대문구', 37.5746183894, 126.9573284067, '서울특별시 서대문구 통일로 251 (현저동)', '12', '서대문 독립공원에 있는 독립관은 일제강점기에 철거되었던 옛 독립협회 사무실로 쓰던 독립관을 고증에 따라 복원한 건물이다. 이 건물은 원래 중국 사신 방문 시 접대를 하던 공간인 영빈관으로 사용하던 모화관 건물을 청·일 전쟁 이후 독립협회에서 사용하던 건물이다. 1894년 이후 서재필이 발의하고 독립협회에서 주도하여 개수한 후 독립관으로 개칭하였다. 이후 이곳에서 애국토론회를 개최하여 자주·민권·자강 사상을 고취하는 장소로 사용하였으며, 독립문과 함께 독립사상을 표현하였으나 일제에 의하여 철거되었다. 독립관은 지상 1층 한식 목조건물로서 정면 6칸, 측면 4칸, 7량 팔작지붕 구조였으며, 원래 위치는 동남쪽으로 약 350m 지점이었다. 서대문독립공원 조성사업계획에 의거 전문가의 고증 자문에 따라 지상층은 당초대로 한식 목조건물로 복원하여 순국선열들의 위패봉안 및 전시실로 사용하고, 지하층은 행사 및 유물 보관을 위해 사용하고 있다. 1996년 서울시에서 건립하였다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/28/2413928_image2_1.jpg', '', 'TOURAPI', '1828571', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 통일로 251 (현저동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"1828571","contenttypeid":"12","createdtime":"20130717192817","firstimage":"https://tong.visitkorea.or.kr/cms/resource/28/2413928_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/28/2413928_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9573284067","mapy":"37.5746183894","mlevel":"6","modifiedtime":"20260910142255","sigungucode":"","tel":"","title":"독립관","zipcode":"03732","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"HS","lclsSystm2":"HS01","lclsSystm3":"HS010100","detail":{"contentid":"1828571","contenttypeid":"12","title":"독립관","createdtime":"2013071