SELECT 'market', '독립문영천시장', '서대문구', 37.5703342733, 126.9618475045, '서울특별시 서대문구 통일로 189-1 (영천동)', '38', '1960년대 서대문구 독립문 인근에 형성된 영천시장은 과거 서울을 대표하는 떡 도매시장으로 유명했던 50년 넘는 역사를 지닌 전통시장이다. 주택가 인근에 있어 인근 주민들이 애용하는 서울의 대표적인 골목형 전통시장으로 서울시는 서대문구 영천시장길 38일대를 2021년 ''7월의 미래 유산''으로 선정했다. 약 198개의 점포가 운영 중인 대규모 전통시장으로 떡볶이와 꽈배기 등 다양한 먹거리를 판매하고 있는 것으로 유명하다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/79/2789779_image2_1.jpg', '', 'TOURAPI', '2789102', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 통일로 189-1 (영천동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2789102","contenttypeid":"38","createdtime":"20211208194231","firstimage":"https://tong.visitkorea.or.kr/cms/resource/79/2789779_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/79/2789779_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9618475045","mapy":"37.5703342733","mlevel":"6","modifiedtime":"20260910163936","sigungucode":"","tel":"","title":"독립문영천시장","zipcode":"03734","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH06","lclsSystm3":"SH060200","detail":{"contentid":"2789102","contenttypeid":"38","title":"독립문영천시장","createdtime":"20211208194231","modifiedtime":"20260910163936","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/79/2789779_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/79/2789779_image3_1.jpg","c