SELECT 'tourapi-2927071', '디스커버리 현대백화점 신촌점', '서대문구', 37.5560830579515, 126.935844876509, '서울특별시 서대문구 신촌로 83 (창천동) 8층', '38', '디스커버리는 탐험 정신을 기반으로 한 글로벌 아웃도어 브랜드로, 내구성과 디자인을 동시에 만족시키는 제품을 제공합니다. 트렌디한 감각과 기능성을 겸비해 젊은 세대에게 인기가 높으며, 아웃도어 활동과 일상 생활 모두에 적합합니다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/59/4019959_image2_1.jpg', '', 'TOURAPI', '2927071', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 신촌로 83 (창천동)","addr2":"8층","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2927071","contenttypeid":"38","createdtime":"20221030230046","firstimage":"https://tong.visitkorea.or.kr/cms/resource/59/4019959_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/59/4019959_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.935844876509","mapy":"37.5560830579515","mlevel":"6","modifiedtime":"20260327092150","sigungucode":"","tel":"","title":"디스커버리 현대백화점 신촌점","zipcode":"03789","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH04","lclsSystm3":"SH040300","detail":{"contentid":"2927071","contenttypeid":"38","title":"디스커버리 현대백화점 신촌점","createdtime":"20221030230046","modifiedtime":"20260327092150","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/59/4019959_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/59/4019959_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH04","lclsSystm3":"SH040300","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 신촌로 83 (창천동)","addr2":"8층","zipcode":"03789","mapx":"126.935844876509","mapy":"37.5560830579515","mlevel":"6","overview":"디스커버리는 탐험 정신을 기반으로 한 글로벌 아웃도어 브랜드로, 내구성과 디자인을 동시에 만족시키는 제품을 제공합니다. 트렌디한 감각과 기능성을 겸비해 젊은 세대에게 인기가 높으며, 아웃도어 활동과 일상 생활 모두에 적합합니다."}}}'
