SELECT 'tourapi-2939587', '라임', '서대문구', 37.5580166891, 126.9387394569, '서울특별시 서대문구 연세로4길 41 2층', '39', '라임은 서울 신촌에 위치한 초밥 전문점으로, 다양한 롤 메뉴를 맛볼 수 있는 곳이다. 아담한 규모의 매장은 깔끔하고 편안한 분위기로 조성되어 있어 부담 없이 식사를 즐기기 좋다. 이곳은 캘리포니아 롤과 덴뿌라 롤을 비롯해 여러 종류의 롤 초밥을 선보이며, 취향에 따라 다양한 메뉴를 선택할 수 있다. 롤 메뉴 외에도 초밥과 돈부리, 커리, 우동 등 다채로운 식사 메뉴를 갖추고 있어 폭넓게 즐길 수 있다. 세트 메뉴도 마련되어 있어 여러 메뉴를 함께 맛보기 좋으며, 신촌에서 일본식 메뉴를 즐기고 싶을 때 방문하기 좋은 식당이다.', 'https://www.data.go.kr/data/15101578/openapi.do', NULL, '', 'TOURAPI', '2939587', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연세로4길 41","addr2":"2층","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2939587","contenttypeid":"39","createdtime":"20221228173434","firstimage":"","firstimage2":"","cpyrhtDivCd":"","mapx":"126.9387394569","mapy":"37.5580166891","mlevel":"6","modifiedtime":"20260605084251","sigungucode":"","tel":"","title":"라임","zipcode":"03777","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020200","detail":{"contentid":"2939587","contenttypeid":"39","title":"라임","createdtime":"20221228173434","modifiedtime":"20260605084251","tel":"","telname":"","homepage":"","firstimage":"","firstimage2":"","cpyrhtDivCd":"","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020200","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연세로4길 41","addr2":"2층","zipcode":"03777","mapx":"126.9387394569","mapy":"37.5580166891","mlevel":"6","overview":"라임은 서울 신촌에 위치한 초밥 전문점으로, 다양한 롤 메뉴를 맛볼 수 있는 곳이다. 아담한 규모의 매장은 깔끔하고 편안한 분위기로 조성되어 있어 부담 없이 식사를 즐기기 좋다. 이곳은 캘리포니아 롤과 덴뿌라 롤을 비롯해 여러 종류의 롤 초밥을 선보이며, 취향에 따라 다양한 메뉴를 선택할 수 있다. 롤 메뉴 외에도 초밥과 돈부리, 커리, 우동 등 다채로운 식사 메뉴를 갖추고 있어 폭넓게 즐길 수 있다. 세트 메뉴도 마련되어 있어 여러 메뉴를 함께 맛보기 좋으며, 신촌에서 일본식 메뉴를 즐기고 싶을 때 방문하기 좋은 식당이다."}}}'
