SELECT 'tourapi-2914252', '락희안 가좌본점', '서대문구', 37.5760977152, 126.924168671, '서울특별시 서대문구 가재울로4길 53 (남가좌동)', '39', '이곳은 서울특별시 서대문구 남가좌동 남가좌파출소 인근에 위치한 중식 전문점이다. 넓고 쾌적한 1층 홀과 여러 개의 룸으로 구성된 2층 공간을 갖추고 있으며, 단체석이 마련되어 있어 가족 외식은 물론 모임과 회식 장소로 이용하기 좋다. 대표 메뉴는 해산물이 푸짐하게 들어간 짬뽕으로, 시원하고 깊은 국물 맛이 특징이다. 바삭하면서도 쫄깃한 식감의 옛날 탕수육도 많은 사람들이 찾는 인기 메뉴이며, 다양한 중식 요리를 함께 즐길 수 있다. 도보 10분 거리에는 카페와 갤러리, 공원 등이 있어 식사 후 여유롭게 둘러보기에도 좋다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/45/2914245_image2_1.jpg', '', 'TOURAPI', '2914252', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 가재울로4길 53 (남가좌동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2914252","contenttypeid":"39","createdtime":"20221121172335","firstimage":"https://tong.visitkorea.or.kr/cms/resource/45/2914245_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/45/2914245_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9241686710","mapy":"37.5760977152","mlevel":"6","modifiedtime":"20260720102627","sigungucode":"","tel":"","title":"락희안 가좌본점","zipcode":"03692","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020100","detail":{"contentid":"2914252","contenttypeid":"39","title":"락희안 가좌본점","createdtime":"20221121172335","modifiedtime":"20260720102627","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/45/2914245_image2_1.jpg","firstimage2":"h