SELECT 'tourapi-3082176', '모두예술극장', '서대문구', 37.560094639936096, 126.96230680303795, '서울특별시 서대문구 충정로 7 (충정로3가)', '14', '모두예술극장은 가변형 블랙박스 공연장이다. 무대와 객석 크기, 위치, 구조 등을 자유롭게 조절함으로써 공연에 따라 다양한 무대와 객석의 형태를 구현할 수 있다. 전체 공간이 무단차로 조성되어 이동에 불편함이 있는 공연자와 기술 스태프들의 활동에 제약이 없는 공연장이다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/17/3505717_image2_1.jpg', '', 'TOURAPI', '3082176', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 충정로 7 (충정로3가)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"3082176","contenttypeid":"14","createdtime":"20231204144230","firstimage":"https://tong.visitkorea.or.kr/cms/resource/17/3505717_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/17/3505717_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.96230680303795","mapy":"37.560094639936096","mlevel":"6","modifiedtime":"20260401094848","sigungucode":"","tel":"","title":"모두예술극장","zipcode":"03737","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE06","lclsSystm3":"VE060100","detail":{"contentid":"3082176","contenttypeid":"14","title":"모두예술극장","createdtime":"20231204144230","modifiedtime":"20260401094848","tel":"","telname":"","homepage":"https://www.moduarttheater.or.kr/home/ko/main","firstimage":"https://tong.visitkorea.or.kr/cms/resource/17/3505717_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/17/3505717_image3_1.jpg","cpyrhtDivCd":"Type3","ar