SELECT 'tourapi-2900401', '모래내곱창', '서대문구', 37.5783972645, 126.9236459053, '서울특별시 서대문구 증가로10길 26', '39', '명지대학교 맞은편 먹자골목에 위치한 모래내곱창은 철판에 초벌 한 야채곱창, 순대곱창, 알곱창이 맛있는 곳이다. 쫄깃한 곱창을 가성비 좋고 푸짐하게 즐길 수 있다. 대표 메뉴는 야채곱창볶음, 순대곱창볶음, 하얀 알곱창, 빨간 알곱창이며, 새로운 곱창을 맛보고 싶을 때 도전해 보기 좋은 곳이다. 곱창을 맛있게 먹은 후 볶음밥을 꼭 같이 먹어주어야 한다. 매장에서 식사를 할 경우 2인분부터 주문이 가능하며, 포장은 1인분부터 가능하다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/54/3578254_image2_1.jpg', '', 'TOURAPI', '2900401', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 증가로10길 26","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2900401","contenttypeid":"39","createdtime":"20221107155322","firstimage":"https://tong.visitkorea.or.kr/cms/resource/54/3578254_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/54/3578254_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9236459053","mapy":"37.5783972645","mlevel":"6","modifiedtime":"20260826163321","sigungucode":"","tel":"","title":"모래내곱창","zipcode":"03665","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","detail":{"contentid":"2900401","contenttypeid":"39","title":"모래내곱창","createdtime":"20221107155322","modifiedtime":"20260826163321","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/54/3578254_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/54/3578254_image3_1.jpg","cpyrht