INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-2839885', '목란', '서대문구', 37.5683847203, 126.9304871893, '서울특별시 서대문구 연희로15길 21', '39', '목란은 중식 요리로 유명한 이연복 셰프가 직접 운영하는 중식당이다. 3층짜리 단독 건물을 사용하여 매장이 크고 넓어 일행과 프라이빗하게 식사를 즐길 수 있다. 대표 메뉴로는 TV 프로그램에 자주 소개되었던 동파육과 멘보샤다. 동파육은 생삼겹살로 6시간 이상의 조리과정을 거쳐 만들어내는 요리이며, 멘보샤는 다진 새우살을 빵 사이에 넣어 튀겨낸 요리다. 이외에도 간장 베이스의 달콤 짭조름한 소고기 요리인 몽골리안 비프와 마라 소스에 볶아낸 소고기 요리인 마라비프, 동구버섯 위에 다진 새우살을 올려 쪄낸 후 어향소스로 맛을 낸 매콤한 어향동구 등의 다양한 중식요리가 준비되어 있다. 전화와 예약 애플리케이션을 통해 예약 운영 중이며, 애플리케이션을 통한 예약이 우선으로 확정된다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/81/2839881_image2_1.jpg', '', 'TOURAPI', '2839885', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희로15길 21","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2839885","contenttypeid":"39","createdtime":"20220819142358","firstimage":"https://tong.visitkorea.or.kr/cms/resource/81/2839881_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/81/2839881_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9304871893","mapy":"37.5683847203","mlevel":"6","modifiedtime":"20261001141437","sigungucode":"","tel":"","title":"목란","zipcode":"03703","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020100","detail":{"contentid":"2839885","contenttypeid":"39","title":"목란","createdtime":"20220819142358","modifiedtime":"20261001141437","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/81/2839881_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/81/2839881_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연희로15길 21","addr2":"","zipcode":"03703","mapx":"126.9304871893","mapy":"37.5683847203","mlevel":"6","overview":"목란은 중식 요리로 유명한 이연복 셰프가 직접 운영하는 중식당이다. 3층짜리 단독 건물을 사용하여 매장이 크고 넓어 일행과 프라이빗하게 식사를 즐길 수 있다. 대표 메뉴로는 TV 프로그램에 자주 소개되었던 동파육과 멘보샤다. 동파육은 생삼겹살로 6시간 이상의 조리과정을 거쳐 만들어내는 요리이며, 멘보샤는 다진 새우살을 빵 사이에 넣어 튀겨낸 요리다. 이외에도 간장 베이스의 달콤 짭조름한 소고기 요리인 몽골리안 비프와 마라 소스에 볶아낸 소고기 요리인 마라비프, 동구버섯 위에 다진 새우살을 올려 쪄낸 후 어향소스로 맛을 낸 매콤한 어향동구 등의 다양한 중식요리가 준비되어 있다. 전화와 예약 애플리케이션을 통해 예약 운영 중이며, 애플리케이션을 통한 예약이 우선으로 확정된다."}}}'
