SELECT 'tourapi-2922822', '미니골드 현대백화점 신촌점', '서대문구', 37.5560830579515, 126.935844876509, '서울특별시 서대문구 신촌로 83 (창천동) B2층', '38', '미니골드는 감각적인 디자인과 합리적인 가치를 지향하는 패션 주얼리 브랜드입니다. 일상에서 가볍게 착용할 수 있는 데일리 아이템부터 화려한 포인트 제품까지 다양한 스타일을 선보여 여성 고객들에게 인기가 높습니다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/74/4019974_image2_1.jpg', '', 'TOURAPI', '2922822', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 신촌로 83 (창천동)","addr2":"B2층","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2922822","contenttypeid":"38","createdtime":"20221101033548","firstimage":"https://tong.visitkorea.or.kr/cms/resource/74/4019974_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/74/4019974_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.935844876509","mapy":"37.5560830579515","mlevel":"6","modifiedtime":"20260327092150","sigungucode":"","tel":"","title":"미니골드 현대백화점 신촌점","zipcode":"03789","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH04","lclsSystm3":"SH040300","detail":{"contentid":"2922822","contenttypeid":"38","title":"미니골드 현대백화점 신촌점","createdtime":"20221101033548","modifiedtime":"20260327092150","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/74/4019974_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/74/4019974_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSign