SELECT 'tourapi-128028', '백련사(서대문)', '서대문구', 37.5863369068, 126.9273795751, '서울특별시 서대문구 백련사길 170-43 (홍은동)', '12', '서대문 백련산 자락에 있는 천년고찰 백련사는 신라 경덕왕 6년(747)에 진표율사가 창건하였다. 당시는 정토사라 하였는데 조선조 정종 원년에 백련사라 개칭하였다. 조선 2대 임금인 정종이 왕위를 태종에게 물려주고 난 뒤에 요양차 이곳에서 머무르기도 했다. 조선 임금 세조의 딸 의숙옹주가 20세에 남편을 잃고 비통함을 달래기 위해 돌아다니다가 여기서 해동묵(엄나무)을 보고 인생의 참뜻을 깨달았다고 한다. 그 후 의숙옹주의 원당으로 정하면서 이름을 백련사로 바꾸었다고 한다. 일설에 의하면 경복궁에서 볼 때 서쪽에 있어서 서방정, 정토사라고 하였는데 어느 여름날 연못에서 갑자기 하얀 연꽃이 피어올라 백련사라고 명칭을 바꾸었다고 전한다. 선조 때 임진왜란으로 소실되었으나 바로 재건하였고, 그 뒤로도 여러 차례 중창을 거듭했다. 1965년 준공한 극락전과 아미타불이 있는 무량수전, 관세음보살이 있는 원통전을 비롯해 약사전, 관음전, 명부전, 삼성각, 독성각, 범종각, 해탈루가 있고 정포대화상과 정토관세음 보살상이 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/12/3401412_image2_1.JPG', '', 'TOURAPI', '128028', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 백련사길 170-43 (홍은동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"128028","contenttypeid":"12","createdtime":"20040108090000","firstimage":"https://tong.visitkorea.or.kr/cms/resource/12/3401412_image2_1.JPG","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/12/3401412_image3_1.JPG","cpyrhtDivCd":"Type3","mapx":"126.9273795751","mapy":"37.5863369068","mlevel":"6","modifiedtime":"20261103115840","sigungucode":"","tel":"","title":"백련사(서대문)","zipcode":"03655","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"HS","lclsSystm2":"HS03","lclsSystm3":"HS030100","detail":{"contentid":"128028","contenttypeid":