INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-2718417', '보틀라운지', '서대문구', 37.5751838550368, 126.928492745891, '서울특별시 서대문구 홍연길 26 (연희동)', '39', '보틀라운지 카페는 보틀팩토리의 첫번째 프로젝트로 만들어진 카페이다. 보틀 팩토리는 많은 플라스틱 테이크아웃 컵들이 정말 재활용되고 있는지에 대한 궁금증을 가지고 연구를 시작했고 결국엔 대부분의 컵들이 재활용 되지 않는다는 점을 알아냈다. 그래서 이 문제를 해결하는 방법은 재활용률을 높이는 것이 아니라 발생 자체를 줄여야 한다고 생각했고 ''일회용품 없는 카페''를 시도했다. 일회용 컵 대신 보증금과 함께 유리병에 음료를 담아 판매하기 시작했고 결과는 이 프로젝트에 공감하는 손님들이 있는 것을 보며 정착되었다.', 'https://www.data.go.kr/data/15101578/openapi.do', NULL, '', 'TOURAPI', '2718417', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 홍연길 26","addr2":"(연희동)","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2718417","contenttypeid":"39","createdtime":"20210526225936","firstimage":"","firstimage2":"","cpyrhtDivCd":"","mapx":"126.928492745891","mapy":"37.5751838550368","mlevel":"6","modifiedtime":"20260312103259","sigungucode":"","tel":"","title":"보틀라운지","zipcode":"03695","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD05","lclsSystm3":"FD050100","detail":{"contentid":"2718417","contenttypeid":"39","title":"보틀라운지","createdtime":"20210526225936","modifiedtime":"20260312103259","tel":"","telname":"","homepage":"","firstimage":"","firstimage2":"","cpyrhtDivCd":"","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD05","lclsSystm3":"FD050100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 홍연길 26","addr2":"(연희동)","zipcode":"03695","mapx":"126.928492745891","mapy":"37.5751838550368","mlevel":"6","overview":"보틀라운지 카페는 보틀팩토리의 첫번째 프로젝트로 만들어진 카페이다. 보틀 팩토리는 많은 플라스틱 테이크아웃 컵들이 정말 재활용되고 있는지에 대한 궁금증을 가지고 연구를 시작했고 결국엔 대부분의 컵들이 재활용 되지 않는다는 점을 알아냈다. 그래서 이 문제를 해결하는 방법은 재활용률을 높이는 것이 아니라 발생 자체를 줄여야 한다고 생각했고 ''일회용품 없는 카페''를 시도했다. 일회용 컵 대신 보증금과 함께 유리병에 음료를 담아 판매하기 시작했고 결과는 이 프로젝트에 공감하는 손님들이 있는 것을 보며 정착되었다."}}}'
