INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-2914233', '복성각', '서대문구', 37.5584688817, 126.9374005236, '서울특별시 서대문구 명물1길 24 (창천동)', '39', '2호선 신촌역 3번 출구에서 도보 10분 거리에 있는 중식당이다. 짜장면, 짬뽕, 탕수육 등 대중적인 중식 메뉴부터 특색 있는 중국식 냉면까지 다양하게 즐길 수 있는 식당이다. 특히 탕수육은 윤기 나는 소스와 바삭한 식감으로 많은 사랑을 받고 있으며, 중국식 냉면은 시원한 맛으로 여름철 인기 메뉴이다. 총 3층 규모로 매장이 크고 단체석이 있어서 모임이나 회식하기 좋으며 대학가 근처에 있어서 주변에 다양한 맛집과 놀거리가 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/28/2914228_image2_1.jpg', '', 'TOURAPI', '2914233', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 명물1길 24 (창천동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2914233","contenttypeid":"39","createdtime":"20221121171747","firstimage":"https://tong.visitkorea.or.kr/cms/resource/28/2914228_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/28/2914228_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9374005236","mapy":"37.5584688817","mlevel":"6","modifiedtime":"20260818113029","sigungucode":"","tel":"","title":"복성각","zipcode":"03776","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020100","detail":{"contentid":"2914233","contenttypeid":"39","title":"복성각","createdtime":"20221121171747","modifiedtime":"20260818113029","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/28/2914228_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/28/2914228_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 명물1길 24 (창천동)","addr2":"","zipcode":"03776","mapx":"126.9374005236","mapy":"37.5584688817","mlevel":"6","overview":"2호선 신촌역 3번 출구에서 도보 10분 거리에 있는 중식당이다.  짜장면, 짬뽕, 탕수육 등 대중적인 중식 메뉴부터 특색 있는 중국식 냉면까지 다양하게 즐길 수 있는 식당이다. 특히 탕수육은 윤기 나는 소스와 바삭한 식감으로 많은 사랑을 받고 있으며, 중국식 냉면은 시원한 맛으로 여름철 인기 메뉴이다. 총 3층 규모로 매장이 크고 단체석이 있어서 모임이나 회식하기 좋으며 대학가 근처에 있어서 주변에 다양한 맛집과 놀거리가 있다."}}}'
