SELECT 'tourapi-126503', '봉원사(서울)', '서대문구', 37.5717780764, 126.9472292784, '서울특별시 서대문구 봉원사길 120 (봉원동)', '12', '천년고찰이자 전통사찰인 봉원사는 2011년 전통사찰로 등록되었으며, 2014년 7월에 아미타괘불도와 범종이 서울특별시 유형문화유산으로 등록되었다. 신행단체로는 관음회, 화엄회, 합창단, 민화회의 법회가 정기적으로 열리고 있으며 부설기관으로는 영산재 보존회, 영산재연수원, (사)한국불교영산재보존회와 범패교육기관인 옥천범음대학이 설립되어 운영되고 있다. 도심 속에 위치한 봉원사는 전통불교의식인 영산재를 국내는 물론 국외로 홍보하며 또한 계승발전을 통해 전통불교의 총본산의 위상에 걸림이 없고, 생활 속에서의 불심증장 도량이 되도록 노력하고 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'http://tong.visitkorea.or.kr/cms/resource/22/3509922_image2_1.jpg', '', 'TOURAPI', '126503', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 봉원사길 120 (봉원동)","addr2":"","areacode":"1","cat1":"A02","cat2":"A0201","cat3":"A02010800","contentid":"126503","contenttypeid":"12","createdtime":"20041230090000","firstimage":"http://tong.visitkorea.or.kr/cms/resource/22/3509922_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/22/3509922_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9472292784","mapy":"37.5717780764","mlevel":"6","modifiedtime":"20250724133731","sigungucode":"14","tel":"","title":"봉원사(서울)","zipcode":"03721","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"HS","lclsSystm2":"HS03","lclsSystm3":"HS030100","detail":{"contentid":"126503","contenttypeid":"12","title":"봉원사(서울)","createdtime":"20041230090000","modifiedtime":"20250724133731","tel":"","telname":"","homepage":"<a href=\"http://bongwonsa.or.kr/index.php\" target=\"_blank\" title=\"새창 : 봉원사 공식