SELECT 'ansan', '서대문 안산(안산자락길)', '서대문구', 37.5769, 126.9452, '서울특별시 서대문구 봉원사길 75-66', '12', '인왕산에서 서쪽으로 비스듬히 뻗어 무악재를 이루고 솟은 산인 서대문 안산은 길마재의 다른 이름인 무악재는 모악재로 부르기도 하였다. 안산에는 안산자락길과 테이블, 전망지, 메타세콰이어숲, 숲속무대, 능안정, 정상에는 봉수대가 있다. 안산자락길은 서울 서대문구에 위치한 안산의 둘레를 따라 조성된 총길이 약 7㎞의 숲길이다. 걷기 좋은 순환형 무장애숲길이며, 보행 약자도 산책할 수 있도록 경사가 완만하게 조성되어 휠체어나 유모차를 이용할 수도 있다. 북카페와 전망지가 있는데, 전망지를 지나 천천히 걸으면 메타세쿼이아 숲이 펼쳐진다. 안산 봉수대에 도착하면 남쪽으로 한강이 보이고 용산, 여의도, 목동 등 서울 남부 지역의 모습을 볼 수 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/25/3509925_image2_1.jpg', '', 'TOURAPI', '2661502', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 봉원사길 75-66","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2661502","contenttypeid":"12","createdtime":"20200630181158","firstimage":"https://tong.visitkorea.or.kr/cms/resource/25/3509925_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/25/3509925_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9452000000","mapy":"37.5769000000","mlevel":"6","modifiedtime":"20260727103437","sigungucode":"","tel":"","title":"서대문 안산(안산자락길)","zipcode":"03721","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"NA","lclsSystm2":"NA01","lclsSystm3":"NA010100","detail":{"contentid":"2661502","contenttypeid":"12","title":"서대문 안산(안산자락길)","createdtime":"20200630181158","modifiedtime":"20260727103437","tel":"","telname":"","homepage":"서대문구 문화관광 https://www.sdm.go.kr/culture/","firstimage":"https://tong.visitkorea.or.kr/cms/resource/25/3509925_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/25/3509925_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"NA","lclsSystm2":"NA01","lclsSystm3":"NA010100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 봉원사길 75-66","addr2":"","zipcode":"03721","mapx":"126.9452000000","mapy":"37.5769000000","mlevel":"6","overview":"인왕산에서 서쪽으로 비스듬히 뻗어 무악재를 이루고 솟은 산인 서대문 안산은 길마재의 다른 이름인 무악재는 모악재로 부르기도 하였다. 안산에는 안산자락길과 테이블, 전망지, 메타세콰이어숲, 숲속무대, 능안정, 정상에는 봉수대가 있다. 안산자락길은 서울 서대문구에 위치한 안산의 둘레를 따라 조성된 총길이 약 7㎞의 숲길이다. 걷기 좋은 순환형 무장애숲길이며, 보행 약자도 산책할 수 있도록 경사가 완만하게 조성되어 휠체어나 유모차를 이용할 수도 있다. 북카페와 전망지가 있는데, 전망지를 지나 천천히 걸으면 메타세쿼이아 숲이 펼쳐진다. 안산 봉수대에 도착하면 남쪽으로 한강이 보이고 용산, 여의도, 목동 등 서울 남부 지역의 모습을 볼 수 있다."}}}'
