INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-128622', '서대문독립공원', '서대문구', 37.5746723659, 126.9573421635, '서울특별시 서대문구 통일로 251 (현저동)', '12', '서대문독립공원은 1945년 8월 15일 광복이 될 때까지 수많은 애국지사와 1960년대 정치적 변동을 겪으면서 많은 시국사범들이 수감되었던 서울구치소가 있었던 곳이다. 서울구치소가 1987년 11월 경기도 의왕시로 옮겨감에 따라 감옥 7동, 사형장, 지하여자감옥 등을 복원하고 탑골공원에서 3·1운동기념탑을 이전하였으며, 1992년 영은문 주초와 연계하여 1992년 8월 15일 서대문독립공원으로 조성하였다. 서대문독립공원은 조국의 독립을 위해 항거하다 옥고를 치렀던 애국지사의 자주독립 정신을 후손에게 기억시키기 위해서 만들어졌다. 독립문, 역사관, 독립관, 순국선열추념탑 등을 유기적으로 연결함과 동시에 시민이용에 불편을 초래했던 노후한 공원시설을 정비하여 공원을 방문하는 학생, 관광객, 시민고객들의 편의를 최대화하였다. 특히, 독립문은 그동안 시민들의 접근을 제한하였으나, 서대문독립공원 재조성 사업으로 인하여 시민들에게 개방하게 되었다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'http://tong.visitkorea.or.kr/cms/resource/05/3590405_image2_1.jpg', '', 'TOURAPI', '128622', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 통일로 251 (현저동)","addr2":"","areacode":"1","cat1":"A02","cat2":"A0202","cat3":"A02020700","contentid":"128622","contenttypeid":"12","createdtime":"20050929090000","firstimage":"http://tong.visitkorea.or.kr/cms/resource/05/3590405_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/05/3590405_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9573421635","mapy":"37.5746723659","mlevel":"6","modifiedtime":"20251231104650","sigungucode":"14","tel":"","title":"서대문독립공원","zipcode":"03732","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE03","lclsSystm3":"VE030500","detail":{"contentid":"128622","contenttypeid":"12","title":"서대문독립공원","createdtime":"20050929090000","modifiedtime":"20251231104650","tel":"","telname":"","homepage":"<a href=\"https://www.sdm.go.kr/culture/attraction/sub2030.do\" target=\"_blank\" title=\"새창 : 서대문구 문화관광 홈페이지로 이동\">https://www.sdm.go.kr/culture</a>","firstimage":"http://tong.visitkorea.or.kr/cms/resource/05/3590405_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/05/3590405_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"1","sigungucode":"14","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE03","lclsSystm3":"VE030500","cat1":"A02","cat2":"A0202","cat3":"A02020700","addr1":"서울특별시 서대문구 통일로 251 (현저동)","addr2":"","zipcode":"03732","mapx":"126.9573421635","mapy":"37.5746723659","mlevel":"6","overview":"서대문독립공원은 1945년 8월 15일 광복이 될 때까지 수많은 애국지사와 1960년대 정치적 변동을 겪으면서 많은 시국사범들이 수감되었던 서울구치소가 있었던 곳이다. 서울구치소가 1987년 11월 경기도 의왕시로 옮겨감에 따라 감옥 7동, 사형장, 지하여자감옥 등을 복원하고 탑골공원에서 3·1운동기념탑을 이전하였으며, 1992년 영은문 주초와 연계하여 1992년 8월 15일 서대문독립공원으로 조성하였다. 서대문독립공원은 조국의 독립을 위해 항거하다 옥고를 치렀던 애국지사의 자주독립 정신을 후손에게 기억시키기 위해서 만들어졌다. 독립문, 역사관, 독립관, 순국선열추념탑 등을 유기적으로 연결함과 동시에 시민이용에 불편을 초래했던 노후한 공원시설을 정비하여 공원을 방문하는 학생, 관광객, 시민고객들의 편의를 최대화하였다. 특히, 독립문은 그동안 시민들의 접근을 제한하였으나, 서대문독립공원 재조성 사업으로 인하여 시민들에게 개방하게 되었다."}}}'
