SELECT 'tourapi-131333', '서대문문화체육회관 실내수영장', '서대문구', 37.5807573408265, 126.93163957989151, '서울특별시 서대문구 백련사길 39 (홍은동)', '28', '서대문문화체육회관 실내수영장은 서대문문화체육회관 본관 2층에 있으며, 일반 수영 강습 및 생존 수영 강습, 아쿠아로빅 등의 강좌를 운영하고 있다. 총 7개의 레인을 보유하고 있으며, 성인풀, 유아풀로 구성되어 다양한 성인 및 어린이 프로그램이 진행되고 있다. 자유 수영을 이용할 경우, 2층에 있는 키오스크에서 티켓을 발권하고 안내데스트에서 팔찌를 받아서 이용해야 한다. 자유 수영 비용이 저렴하여 평일이나 주말을 이용하여 자유 수영을 즐기기에 좋다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/02/3504102_image2_1.PNG', '', 'TOURAPI', '131333', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 백련사길 39 (홍은동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"131333","contenttypeid":"28","createdtime":"20020716090000","firstimage":"https://tong.visitkorea.or.kr/cms/resource/02/3504102_image2_1.PNG","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/02/3504102_image3_1.PNG","cpyrhtDivCd":"Type3","mapx":"126.93163957989151","mapy":"37.5807573408265","mlevel":"6","modifiedtime":"20260312091904","sigungucode":"","tel":"","title":"서대문문화체육회관 실내수영장","zipcode":"03657","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"LS","lclsSystm2":"LS02","lclsSystm3":"LS020700","detail":{"contentid":"131333","contenttypeid":"28","title":"서대문문화체육회관 실내수영장","createdtime":"20020716090000","modifiedtime":"20260312091904","tel":"","telname":"","homepage":"https://cs.sscmc.or.kr/sdmcs","firstimage":"https://tong.visitkorea.or.kr/cms/resource/02/3504102_image2_1.PNG","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/02/3504102_image3_1.PNG","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"LS","lclsSystm2":"LS02","lclsSystm3":"LS020700","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 백련사길 39 (홍은동)","addr2":"","zipcode":"03657","mapx":"126.93163957989151","mapy":"37.5807573408265","mlevel":"6","overview":"서대문문화체육회관 실내수영장은 서대문문화체육회관 본관 2층에 있으며, 일반 수영 강습 및 생존 수영 강습, 아쿠아로빅 등의 강좌를 운영하고 있다. 총 7개의 레인을 보유하고 있으며, 성인풀, 유아풀로 구성되어 다양한 성인 및 어린이 프로그램이 진행되고 있다. 자유 수영을 이용할 경우, 2층에 있는 키오스크에서 티켓을 발권하고 안내데스트에서 팔찌를 받아서 이용해야 한다. 자유 수영 비용이 저렴하여 평일이나 주말을 이용하여 자유 수영을 즐기기에 좋다."}}}'
