INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-130448', '서대문자연사박물관', '서대문구', 37.5766949504464, 126.93783623533, '서울특별시 서대문구 연희로32길 51', '14', '서대문자연사박물관은 서울 도심 속 안산 자락에 위치한 공공 자연사박물관으로, 2003년 7월 10일에 개관하였다. 이 박물관은 공공기관에 의해 설립되었으며, 시민들에게 자연에 대한 이해를 높이고 특히 꿈 많은 어린이와 청소년들이 다양한 생물과 지질, 환경에 대한 정보를 직접 보고 체험할 수 있는 기회를 제공한다. 박물관은 전시뿐만 아니라 교육 프로그램과 체험 활동을 통해 자연에 대한 지식과 흥미를 동시에 제공한다. 또한 지역 주민들에게는 문화 활동 공간으로서의 역할도 수행하고 있다. 서대문자연사박물관은 도시 생활 속에서도 생명과 자연의 가치를 체감할 수 있는 기회를 제공하고 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/76/3502776_image2_1.jpg', '', 'TOURAPI', '130448', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희로32길 51","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"130448","contenttypeid":"14","createdtime":"20071106105807","firstimage":"https://tong.visitkorea.or.kr/cms/resource/76/3502776_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/76/3502776_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.93783623533","mapy":"37.5766949504464","mlevel":"6","modifiedtime":"20260312090840","sigungucode":"","tel":"","title":"서대문자연사박물관","zipcode":"03718","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE07","lclsSystm3":"VE070100","detail":{"contentid":"130448","contenttypeid":"14","title":"서대문자연사박물관","createdtime":"20071106105807","modifiedtime":"20260312090840","tel":"","telname":"","homepage":"http://namu.sdm.go.kr","firstimage":"https://tong.visitkorea.or.kr/cms/resource/76/3502776_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/76/3502776_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE07","lclsSystm3":"VE070100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연희로32길 51","addr2":"","zipcode":"03718","mapx":"126.93783623533","mapy":"37.5766949504464","mlevel":"6","overview":"서대문자연사박물관은 서울 도심 속 안산 자락에 위치한 공공 자연사박물관으로, 2003년 7월 10일에 개관하였다. 이 박물관은 공공기관에 의해 설립되었으며, 시민들에게 자연에 대한 이해를 높이고 특히 꿈 많은 어린이와 청소년들이 다양한 생물과 지질, 환경에 대한 정보를 직접 보고 체험할 수 있는 기회를 제공한다. 박물관은 전시뿐만 아니라 교육 프로그램과 체험 활동을 통해 자연에 대한 지식과 흥미를 동시에 제공한다. 또한 지역 주민들에게는 문화 활동 공간으로서의 역할도 수행하고 있다. 서대문자연사박물관은 도시 생활 속에서도 생명과 자연의 가치를 체감할 수 있는 기회를 제공하고 있다."}}}'
