INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'prison', '서대문형무소역사관', '서대문구', 37.574303895, 126.9555345762, '서울특별시 서대문구 통일로 251', '14', '서대문형무소는 대한제국 말 일제의 강압으로 세워진 이래, 80여 년간 격동의 근현대 수난사를 간직한 현장이자 대표적인 일제 탄압기관이었다. 1908년 10월 21일 경성감옥이라는 이름으로 문을 연 뒤 일제에 국권을 빼앗기자, 이에 항거하는 민족독립운동이 전국에서 거세게 일어났고 일제는 수많은 애국지사를 체포·투옥했다. 수용 인원이 늘어나자 마포 공덕동에 새 감옥을 지으면서, 기존 감옥은 1912년 9월 3일 서대문감옥으로 명칭이 바뀌었다. 이후 수많은 민족 수난의 역사를 거쳐 1992년 8월 15일 현재의 서대문독립공원으로 개원하였다. 서대문구에서는 1995년부터 서대문독립공원 사적지에 대한 성역화 사업을 추진하였다. 조국 독립을 위해 일제에 맞서다 투옥되어 모진 고문과 탄압 끝에 순국하신 애국선열들의 넋을 기리고, 후손들에게 자주독립 정신을 일깨워 주는 역사의 산 교육장으로 삼고자 이곳을 새롭게 단장하여 서대문형무소역사관으로 개관하였다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/29/3520329_image2_1.jpg', '', 'TOURAPI', '130152', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 통일로 251","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"130152","contenttypeid":"14","createdtime":"20071106104433","firstimage":"https://tong.visitkorea.or.kr/cms/resource/29/3520329_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/29/3520329_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9555345762","mapy":"37.5743038950","mlevel":"6","modifiedtime":"20260810113022","sigungucode":"","tel":"","title":"서대문형무소역사관","zipcode":"03732","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE07","lclsSystm3":"VE070300","detail":{"contentid":"130152","contenttypeid":"14","title":"서대문형무소역사관","createdtime":"20071106104433","modifiedtime":"20260810113022","tel":"","telname":"","homepage":"http://sphh.sscmc.or.kr","firstimage":"https://tong.visitkorea.or.kr/cms/resource/29/3520329_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/29/3520329_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE07","lclsSystm3":"VE070300","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 통일로 251","addr2":"","zipcode":"03732","mapx":"126.9555345762","mapy":"37.5743038950","mlevel":"6","overview":"서대문형무소는 대한제국 말 일제의 강압으로 세워진 이래, 80여 년간 격동의 근현대 수난사를 간직한 현장이자 대표적인 일제 탄압기관이었다. 1908년 10월 21일 경성감옥이라는 이름으로 문을 연 뒤 일제에 국권을 빼앗기자, 이에 항거하는 민족독립운동이 전국에서 거세게 일어났고 일제는 수많은 애국지사를 체포·투옥했다. 수용 인원이 늘어나자 마포 공덕동에 새 감옥을 지으면서, 기존 감옥은 1912년 9월 3일 서대문감옥으로 명칭이 바뀌었다. 이후 수많은 민족 수난의 역사를 거쳐 1992년 8월 15일 현재의 서대문독립공원으로 개원하였다.\n서대문구에서는 1995년부터 서대문독립공원 사적지에 대한 성역화 사업을 추진하였다. 조국 독립을 위해 일제에 맞서다 투옥되어 모진 고문과 탄압 끝에 순국하신 애국선열들의 넋을 기리고, 후손들에게 자주독립 정신을 일깨워 주는 역사의 산 교육장으로 삼고자 이곳을 새롭게 단장하여 서대문형무소역사관으로 개관하였다."}}}'
WHERE NOT EXISTS (SELECT 1 FROM catalog_place WHERE id = 'prison');

INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-252532', '서울 연세대학교 스팀슨관', '서대문구', 37.5660945924, 126.9382483586, '서울특별시 서대문구 연세로 50 (신촌동)', '12', '연세대학교에 최초로 세워진 건물로서, 1919년 착공하여 1920년 완성된 돌로 지은 2층 건물이다. 연세대학교의 전신인 연희전문학교의 설립자 언더우드(한국 이름 원두우) 목사가 고향인 미국으로 돌아가서 항구적인 학교 건축을 위해 미국 로스앤젤레스에 거주하던 찰스 스팀슨의 기부금을 얻어놓고 세상을 떠난 뒤 후임 교장인 에비슨이 그 기부금으로 건립한 것이다. 유가족인 언더우드 부인이 초석을 놓았고 당시 화학과 교수인 밀러가 공사를 감독하였다. 설계자는 알 수 없으나 당시 미국인 건축가들이 우리나라에 와서 설계와 기본 계획을 작성하였다고 한다. 장방형의 평면에 맞배지붕을 하고 있으며 고딕 양식의 건물이다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/00/4123100_image2_1.jpg', '', 'TOURAPI', '252532', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연세로 50 (신촌동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"252532","contenttypeid":"12","createdtime":"20071025090000","firstimage":"https://tong.visitkorea.or.kr/cms/resource/00/4123100_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/00/4123100_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9382483586","mapy":"37.5660945924","mlevel":"6","modifiedtime":"20261014152229","sigungucode":"","tel":"","title":"서울 연세대학교 스팀슨관","zipcode":"03722","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"HS","lclsSystm2":"HS01","lclsSystm3":"HS011100","detail":{"contentid":"252532","contenttypeid":"12","title":"서울 연세대학교 스팀슨관","createdtime":"20071025090000","modifiedtime":"20261014152229","tel":"","telname":"","homepage":"https://www.khs.go.kr/","firstimage":"https://tong.visitkorea.or.kr/cms/resource/00/4123100_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/00/4123100_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"HS","lclsSystm2":"HS01","lclsSystm3":"HS011100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연세로 50 (신촌동)","addr2":"","zipcode":"03722","mapx":"126.9382483586","mapy":"37.5660945924","mlevel":"6","overview":"연세대학교에 최초로 세워진 건물로서, 1919년 착공하여 1920년 완성된 돌로 지은 2층 건물이다. 연세대학교의 전신인 연희전문학교의 설립자 언더우드(한국 이름 원두우) 목사가 고향인 미국으로 돌아가서 항구적인 학교 건축을 위해 미국 로스앤젤레스에 거주하던 찰스 스팀슨의 기부금을 얻어놓고 세상을 떠난 뒤 후임 교장인 에비슨이 그 기부금으로 건립한 것이다. 유가족인 언더우드 부인이 초석을 놓았고 당시 화학과 교수인 밀러가 공사를 감독하였다. 설계자는 알 수 없으나 당시 미국인 건축가들이 우리나라에 와서 설계와 기본 계획을 작성하였다고 한다. 장방형의 평면에 맞배지붕을 하고 있으며 고딕 양식의 건물이다."}}}'
