INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-252534', '서울 연세대학교 아펜젤러관', '서대문구', 37.5659, 126.939, '서울특별시 서대문구 연세로 50', '12', '연세대학교 서울캠퍼스 안에 있는 아펜젤러관은 연세대학교의 본관 건물인 스팀슨관의 맞은편에 위치하고 있다. 이 건물은 미국 북감리 교회 최초의 선교사이자 배재학당을 설립한 아펜젤러를 기념하기 위하여 미국 매사추세츠주 피츠필드시의 제일감리교회의 기부금으로 지어졌다. 스팀슨관과 언더우드관과 마찬가지로 화학과 교수인 밀러의 감독하에 1921년 짓기 시작하여 1924년에 완성되었다. 아펜젤러관은 스팀슨관과 언더우드관의 두 건물과 함께 ㄷ자형의 캠퍼스를 구성하며, 중앙에 있는 언더우드관의 오른쪽에 자리 잡고 있다. 평면은 장방형이며 중앙에 현관과 계단실이 있고 본래는 이학관으로 자연과학계의 교사로 쓰였고 해방 후에는 상경관으로 상경계통에서 사용하였으나, 현재는 행정관으로 활용하고 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/07/4123107_image2_1.jpg', '', 'TOURAPI', '252534', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연세로 50","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"252534","contenttypeid":"12","createdtime":"20071025090000","firstimage":"https://tong.visitkorea.or.kr/cms/resource/07/4123107_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/07/4123107_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9390000000","mapy":"37.5659000000","mlevel":"6","modifiedtime":"20261014151210","sigungucode":"","tel":"","title":"서울 연세대학교 아펜젤러관","zipcode":"03722","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"HS","lclsSystm2":"HS01","lclsSystm3":"HS011100","detail":{"contentid":"252534","contenttypeid":"12","title":"서울 연세대학교 아펜젤러관","createdtime":"20071025090000","modifiedtime":"20261014151210","tel":"","telname":"","homepage":"https://www.heritage.go.kr/heri","firstimage":"https://tong.visitkorea.or.kr/cms/resource/07/4123107_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/07/4123107_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"HS","lclsSystm2":"HS01","lclsSystm3":"HS011100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연세로 50","addr2":"","zipcode":"03722","mapx":"126.9390000000","mapy":"37.5659000000","mlevel":"6","overview":"연세대학교 서울캠퍼스 안에 있는 아펜젤러관은 연세대학교의 본관 건물인 스팀슨관의 맞은편에 위치하고 있다. 이 건물은 미국 북감리 교회 최초의 선교사이자 배재학당을 설립한 아펜젤러를 기념하기 위하여 미국 매사추세츠주 피츠필드시의 제일감리교회의 기부금으로 지어졌다. 스팀슨관과 언더우드관과 마찬가지로 화학과 교수인 밀러의 감독하에 1921년 짓기 시작하여 1924년에 완성되었다. 아펜젤러관은 스팀슨관과 언더우드관의 두 건물과 함께 ㄷ자형의 캠퍼스를 구성하며, 중앙에 있는 언더우드관의 오른쪽에 자리 잡고 있다. 평면은 장방형이며 중앙에 현관과 계단실이 있고 본래는 이학관으로 자연과학계의 교사로 쓰였고 해방 후에는 상경관으로 상경계통에서 사용하였으나, 현재는 행정관으로 활용하고 있다."}}}'
