INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-252533', '서울 연세대학교 언더우드관', '서대문구', 37.5664, 126.9389, '서울특별시 서대문구 연세로 50', '12', '연세대학교 신촌캠퍼스안에 있는 언더우드관은 이 학교의 전신인 연희전문학교 창립자인 언더우드를 기념하기 위하여 그의 형인 존 티 언더우드의 10만 달러 기부금으로 지어졌다. 1921년 짓기 시작하여 1924년에 완공되었으며 감독은 당시 화학과 교수였던 밀러가 담당했다. 연세대학교 정문에 들어서면 캠퍼스의 중앙을 가로지른 백양로의 끝자락에 자리 잡고 있다. 이 건물의 5층으로 된 중앙의 탑은 이 캠퍼스의 중심 역할을 하고 있다. 본래 강의동으로 사용되었지만, 현재에는 대학본부 건물로 총장실을 비롯한 중요 행정부서가 있다. 구조는 돌구조로서 지하 1층, 지상 3층이며, 탑 부분은 5층이다. 이 건물은 1950년에 한국 전쟁으로 소실되어 내부와 지붕부가 크게 파괴되었으며, 전후 복구되었고 그 보존 상태가 우수하여 역사적 가치가 크다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/11/4123111_image2_1.jpg', '', 'TOURAPI', '252533', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연세로 50","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"252533","contenttypeid":"12","createdtime":"20071025090000","firstimage":"https://tong.visitkorea.or.kr/cms/resource/11/4123111_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/11/4123111_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9389000000","mapy":"37.5664000000","mlevel":"6","modifiedtime":"20261014152516","sigungucode":"","tel":"","title":"서울 연세대학교 언더우드관","zipcode":"03722","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"HS","lclsSystm2":"HS01","lclsSystm3":"HS011100","detail":{"contentid":"252533","contenttypeid":"12","title":"서울 연세대학교 언더우드관","createdtime":"20071025090000","modifiedtime":"20261014152516","tel":"","telname":"","homepage":"https://www.heritage.go.kr","firstimage":"https://tong.visitkorea.or.kr/cms/resource/11/4123111_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/11/4123111_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"HS","lclsSystm2":"HS01","lclsSystm3":"HS011100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연세로 50","addr2":"","zipcode":"03722","mapx":"126.9389000000","mapy":"37.5664000000","mlevel":"6","overview":"연세대학교 신촌캠퍼스안에 있는 언더우드관은 이 학교의 전신인 연희전문학교 창립자인 언더우드를 기념하기 위하여 그의 형인 존 티 언더우드의 10만 달러 기부금으로 지어졌다. 1921년 짓기 시작하여 1924년에 완공되었으며 감독은 당시 화학과 교수였던 밀러가 담당했다. 연세대학교 정문에 들어서면 캠퍼스의 중앙을 가로지른 백양로의 끝자락에 자리 잡고 있다. 이 건물의 5층으로 된 중앙의 탑은 이 캠퍼스의 중심 역할을 하고 있다. 본래 강의동으로 사용되었지만, 현재에는 대학본부 건물로 총장실을 비롯한 중요 행정부서가 있다. 구조는 돌구조로서 지하 1층, 지상 3층이며, 탑 부분은 5층이다. 이 건물은 1950년에 한국 전쟁으로 소실되어 내부와 지붕부가 크게 파괴되었으며, 전후 복구되었고 그 보존 상태가 우수하여 역사적 가치가 크다."}}}'
