SELECT 'tourapi-130767', '서울특별시교육청 서대문도서관', '서대문구', 37.58331862, 126.9408580173, '서울특별시 서대문구 모래내로 412 (연희동)', '14', '서울특별시교육청 서대문도서관은 녹음이 우거진 안산도시자연공원 안에 자리 잡고 있다. 20만여 권의 장서와 디지털 환경을 제공하고 매달 독서문화행사를 운영하고 있으며 도서관 1층에는 어린이실, 시청각실, 문화교실, 서고, 북 카페 등이 있고 2층에는 디지털 연속간행물실, 3층에는 종합자료실, 4층에는 자율학습실, 노트북실, 휴게실이 있으며 이용 시간은 각각 상이하다. 이외에도 도서관 이용자들을 위한 북 큐레이션 공간과 다양한 영화를 관람할 수 있는 시네마 갤러리 등 조성되어 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/89/4103689_image2_1.jpg', '', 'TOURAPI', '130767', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 모래내로 412 (연희동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"130767","contenttypeid":"14","createdtime":"20060320090000","firstimage":"https://tong.visitkorea.or.kr/cms/resource/89/4103689_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/89/4103689_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9408580173","mapy":"37.5833186200","mlevel":"6","modifiedtime":"20260825093121","sigungucode":"","tel":"","title":"서울특별시교육청 서대문도서관","zipcode":"03717","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE09","lclsSystm3":"VE090300","detail":{"contentid":"130767","contenttypeid":"14","title":"서울특별시교육청 서대문도서관","createdtime":"20060320090000","modifiedtime":"20260825093121","tel":"","telname":"","homepage":"http://sdmlib.sen.go.kr/","firstimage":"https://tong.visitkorea.or.kr/cms/resource/89/4103689_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/89/4103689_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE09","lclsSystm3":"VE090300","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 모래내로 412 (연희동)","addr2":"","zipcode":"03717","mapx":"126.9408580173","mapy":"37.5833186200","mlevel":"6","overview":"서울특별시교육청 서대문도서관은 녹음이 우거진 안산도시자연공원 안에 자리 잡고 있다. 20만여 권의 장서와 디지털 환경을 제공하고 매달 독서문화행사를 운영하고 있으며 도서관 1층에는 어린이실, 시청각실, 문화교실, 서고, 북 카페 등이 있고 2층에는 디지털 연속간행물실, 3층에는 종합자료실, 4층에는 자율학습실, 노트북실, 휴게실이 있으며 이용 시간은 각각 상이하다. 이외에도 도서관 이용자들을 위한 북 큐레이션 공간과 다양한 영화를 관람할 수 있는 시네마 갤러리 등 조성되어 있다."}}}'
