SELECT 'tourapi-2828401', '소바연구소', '서대문구', 37.5587749428272, 126.939453254545, '서울특별시 서대문구 명물길 50-9', '39', '신촌에 위치하였으며, 직접 뽑은 수제메밀이라 독특하며 맛있는 맛을 자부한다. 소바에 고등어가 올라가는 재치 있는 메뉴도 있어 도전해볼만 하다. 또한 와사비가 구비되어 있지 않으며 대신 고추장아찌가 준비되어 있어 색다른 맛을 느낄 수 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', NULL, '', 'TOURAPI', '2828401', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 명물길 50-9","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2828401","contenttypeid":"39","createdtime":"20220720152733","firstimage":"","firstimage2":"","cpyrhtDivCd":"","mapx":"126.939453254545","mapy":"37.5587749428272","mlevel":"6","modifiedtime":"20260211101150","sigungucode":"","tel":"","title":"소바연구소","zipcode":"03777","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020200","detail":{"contentid":"2828401","contenttypeid":"39","title":"소바연구소","createdtime":"20220720152733","modifiedtime":"20260211101150","tel":"","telname":"","homepage":"","firstimage":"","firstimage2":"","cpyrhtDivCd":"","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020200","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 명물길 50-9","addr2":"","zipcode":"03777","mapx":"126.939453254545","mapy":"37.5587749428272","mlevel":"6","overview":"신촌에 위치하였으며, 직접 뽑은 수제메밀이라 독특하며 맛있는 맛을 자부한다. 소바에 고등어가 올라가는 재치 있는 메뉴도 있어 도전해볼만 하다. 또한 와사비가 구비되어 있지 않으며 대신 고추장아찌가 준비되어 있어 색다른 맛을 느낄 수 있다."}}}'
