SELECT 'tourapi-845319', '수빈', '서대문구', 37.5718038165155, 126.934300608622, '서울특별시 서대문구 연희로25길 31-3', '39', '서울시 서대문구 연희동에 위치한 수빈은 떡갈비로 유명한 한식전문점이다. 떡갈비는 100% 소고기를 직접 다져서 만들며, 주문받는 즉시 구워 뜨거운 철판 위에 정갈하게 내어진다. 두툼하지만 식감이 부드러워 온 가족이 함께 즐기기에 안성맞춤이다. 떡갈비와 함께 나가는 다양한 종류의 밑반찬도 매력적이다. 간장게장정식과 보리굴비정식 또한 인기메뉴이다.', 'https://www.data.go.kr/data/15101578/openapi.do', NULL, '', 'TOURAPI', '845319', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희로25길 31-3","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"845319","contenttypeid":"39","createdtime":"20091029071001","firstimage":"","firstimage2":"","cpyrhtDivCd":"","mapx":"126.934300608622","mapy":"37.5718038165155","mlevel":"6","modifiedtime":"20260409155705","sigungucode":"","tel":"","title":"수빈","zipcode":"03699","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","detail":{"contentid":"845319","contenttypeid":"39","title":"수빈","createdtime":"20091029071001","modifiedtime":"20260409155705","tel":"","telname":"","homepage":"","firstimage":"","firstimage2":"","cpyrhtDivCd":"","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연희로25길 31-3","addr2":"","zipcode":"03699","mapx":"126.934300608622","mapy":"37.5718038165155","mlevel":"6","overview":"서울시 서대문구 연희동에 위치한 수빈은 떡갈비로 유명한 한식전문점이다. 떡갈비는 100% 소고기를 직접 다져서 만들며, 주문받는 즉시 구워 뜨거운 철판 위에 정갈하게 내어진다. 두툼하지만 식감이 부드러워 온 가족이 함께 즐기기에 안성맞춤이다. 떡갈비와 함께 나가는 다양한 종류의 밑반찬도 매력적이다. 간장게장정식과 보리굴비정식 또한 인기메뉴이다."}}}'
