SELECT 'tourapi-142765', '스위스 그랜드 호텔', '서대문구', 37.5884666461, 126.9357749512, '서울특별시 서대문구 연희로 353 (홍은동)', '32', '백련산 자락의 울창한 숲과 맑은 공기, 빼어난 경관 등 산림이 지닌 3박자를 고루 갖춘 도심 속 휴양지를 지향하는 스위스 그랜드 호텔은 수려한 백련산과 홍제천, 안산 자락길 등 도심 속에서 자연을 만끽할 수 있어 일상에 지친 몸과 마음을 쉬게 하기 좋은 곳이다. 396개의 메인 객실과 한국 서비스 레지던스 문화를 선도해 온 그랜드 스위트, 미식의 즐거움을 선사하는 다양한 레스토랑과 바, 그리고 최첨단 시설을 갖춘 초대형 컨벤션 센터를 보유하고 있다. 서울 도심과 인접해 있을 뿐만 아니라, 객실에서 백련산과 홍제천의 아름다운 자연경관을 감상할 수 있다. 지친 몸과 마음을 달래기에 더할 나위 없이 좋은 곳이다. 스위스 그랜드 호텔의 품격 있는 서비스는 비즈니스와 휴식 모두를 위한 이상적인 안식처가 될 것이다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/89/3534089_image2_1.jpg', '', 'TOURAPI', '142765', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희로 353 (홍은동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"142765","contenttypeid":"32","createdtime":"20030324090000","firstimage":"https://tong.visitkorea.or.kr/cms/resource/89/3534089_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/89/3534089_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9357749512","mapy":"37.5884666461","mlevel":"6","modifiedtime":"20261014093449","sigungucode":"","tel":"","title":"스위스 그랜드 호텔","zipcode":"03650","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"AC","lclsSystm2":"AC01","lclsSystm3":"AC010100","detail":{"contentid":"142765","contenttypeid":"32","title":"스위스 그랜드 호텔","createdtime":"20030324090000","modifiedtime":"20261014093449","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/89/3534089_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/89/3534089_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"AC","lclsSystm2":"AC01","lclsSystm3":"AC010100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연희로 353 (홍은동)","addr2":"","zipcode":"03650","mapx":"126.9357749512","mapy":"37.5884666461","mlevel":"6","overview":"백련산 자락의 울창한 숲과 맑은 공기, 빼어난 경관 등 산림이 지닌 3박자를 고루 갖춘 도심 속 휴양지를 지향하는 스위스 그랜드 호텔은 수려한 백련산과 홍제천, 안산 자락길 등 도심 속에서 자연을 만끽할 수 있어 일상에 지친 몸과 마음을 쉬게 하기 좋은 곳이다.\n396개의 메인 객실과 한국 서비스 레지던스 문화를 선도해 온 그랜드 스위트, 미식의 즐거움을 선사하는 다양한 레스토랑과 바, 그리고 최첨단 시설을 갖춘 초대형 컨벤션 센터를 보유하고 있다. 서울 도심과 인접해 있을 뿐만 아니라, 객실에서 백련산과 홍제천의 아름다운 자연경관을 감상할 수 있다. 지친 몸과 마음을 달래기에 더할 나위 없이 좋은 곳이다. 스위스 그랜드 호텔의 품격 있는 서비스는 비즈니스와 휴식 모두를 위한 이상적인 안식처가 될 것이다."}}}'
WHERE NOT EXISTS (SELECT 1 FROM catalog_place WHERE id = 'tourapi-142765');

