SELECT 'tourapi-2924041', '스톤헨지 현대백화점 신촌점', '서대문구', 37.5560830579515, 126.935844876509, '서울특별시 서대문구 신촌로 83 (창천동)', '38', '스톤헨지는 "선이 아름다운 주얼리"라는 슬로건 아래 섬세하고 클래식한 디자인을 선보이는 브랜드입니다. 변치 않는 우아함을 담은 목걸이, 귀걸이 등은 여성들의 일상에 은은한 빛을 더해줍니다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/64/4019964_image2_1.jpg', '', 'TOURAPI', '2924041', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 신촌로 83 (창천동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2924041","contenttypeid":"38","createdtime":"20221030180435","firstimage":"https://tong.visitkorea.or.kr/cms/resource/64/4019964_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/64/4019964_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.935844876509","mapy":"37.5560830579515","mlevel":"6","modifiedtime":"20260327092150","sigungucode":"","tel":"","title":"스톤헨지 현대백화점 신촌점","zipcode":"03789","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH04","lclsSystm3":"SH040300","detail":{"contentid":"2924041","contenttypeid":"38","title":"스톤헨지 현대백화점 신촌점","createdtime":"20221030180435","modifiedtime":"20260327092150","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/64/4019964_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/64/4019964_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSy