SELECT 'tourapi-2851231', '시도 플레이스', '서대문구', 37.5663339265, 126.9283367101, '서울특별시 서대문구 연희맛로 7-7', '39', '‘미니멀에 기반하여 매일 다른 옷, 다양한 실루엣을 연출할 수 있는 옷장을 모두가 가질 수 있게 하자’ 라는 생각에서 시도의 브랜드 스토리가 시작되었다. 복식에 대한 끝없는 고민을 통해 원단, 봉제, 마감의 완성도를 높여 시즌이 지나도 여전히 빛날 수 있는 컬렉션을 전개한다. 시도플레이스는 마냥 옷가게는 아니다. 1층에는 카페가 있고 2층에는 매장이 있는데 이뿐아니라 cd플레이어를 청음할 수 있는 곳부터 책이 놓여진 포토존까지 그야말로 복합문화공간이라고 할 수 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'http://tong.visitkorea.or.kr/cms/resource/80/2849780_image2_1.jpg', '', 'TOURAPI', '2851231', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희맛로 7-7","addr2":"","areacode":"1","cat1":"A05","cat2":"A0502","cat3":"A05020900","contentid":"2851231","contenttypeid":"39","createdtime":"20220907150446","firstimage":"http://tong.visitkorea.or.kr/cms/resource/80/2849780_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/80/2849780_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9283367101","mapy":"37.5663339265","mlevel":"6","modifiedtime":"20250808160932","sigungucode":"14","tel":"","title":"시도 플레이스","zipcode":"03707","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD05","lclsSystm3":"FD050100","detail":{"contentid":"2851231","contenttypeid":"39","title":"시도 플레이스","createdtime":"20220907150446","modifiedtime":"20250808160932","tel":"","telname":"","homepage":"","firstimage":"http://tong.visitkorea.or.kr/cms/resource/80/2849780_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/80/2849780_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"1","sigungucode":"14","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD05","lclsSystm3":"FD050100","cat1":"A05","cat2":"A0502","cat3":"A05020900","addr1":"서울특별시 서대문구 연희맛로 7-7","addr2":"","zipcode":"03707","mapx":"126.9283367101","mapy":"37.5663339265","mlevel":"6","overview":"‘미니멀에 기반하여 매일 다른 옷, 다양한 실루엣을 연출할 수 있는 옷장을 모두가 가질 수 있게 하자’ 라는 생각에서 시도의 브랜드 스토리가 시작되었다. 복식에 대한 끝없는 고민을 통해 원단, 봉제, 마감의 완성도를 높여 시즌이 지나도 여전히 빛날 수 있는 컬렉션을 전개한다. 시도플레이스는 마냥 옷가게는 아니다. 1층에는 카페가 있고 2층에는 매장이 있는데 이뿐아니라 cd플레이어를 청음할 수 있는 곳부터 책이 놓여진 포토존까지 그야말로 복합문화공간이라고 할 수 있다."}}}'
WHERE NOT EXISTS (SELECT 1 FROM catalog_place WHERE id = 'tourapi-2851231');

INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-2783484', '신기한놀이터 떼굴떼굴', '서대문구', 37.5856, 126.9385, '서울특별시 서대문구 홍제동 산 41-29', '12', '놀이터 떼굴떼굴은 서울특별시 서대문구 주택가와 산자락 인근의 야외 공간에 조성된 자연 모래 놀이터이다. 서대문구가 어린이가 바라고 꿈꾸는 놀이터를 만들기 위해 조성한 공간으로, 2019년 11월 개장했다. 놀이터는 3개의 원형 모래놀이터로 구성되어 있으며, 세족장과 음수대, 공중화장실 등의 편의시설이 마련되어 있다. 원목 놀이기구와 천연목재 산책로, 황토 포장 등 자연 소재를 활용한 시설이 조성되어 있으며, 자연 지형과 주변 환경을 활용해 놀이공간을 구성했다. 주요 놀이시설로 롱미끄럼틀과 집라인 등이 있으며, 관리사무실 앞에는 어린이 자전거와 모래놀이 도구가 마련되어 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/42/3565342_image2_1.jpg', '', 'TOURAPI', '2783484', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 홍제동","addr2":"산 41-29","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2783484","contenttypeid":"12","createdtime":"20211130195550","firstimage":"https://tong.visitkorea.or.kr/cms/resource/42/3565342_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/42/3565342_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9385000000","mapy":"37.5856000000","mlevel":"6","modifiedtime":"20260914155920","sigungucode":"","tel":"","title":"신기한놀이터 떼굴떼굴","zipcode":"03644","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"EX","lclsSystm2":"EX07","lclsSystm3":"EX070200","detail":{"contentid":"2783484","contenttypeid":"12","title":"신기한놀이터 떼굴떼굴","createdtime":"20211130195550","modifiedtime":"20260914155920","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/42/3565342_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/42/3565342_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"EX","lclsSystm2":"EX07","lclsSystm3":"EX070200","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 홍제동","addr2":"산 41-29","zipcode":"03644","mapx":"126.9385000000","mapy":"37.5856000000","mlevel":"6","overview":"놀이터 떼굴떼굴은 서울특별시 서대문구 주택가와 산자락 인근의 야외 공간에 조성된 자연 모래 놀이터이다. 서대문구가 어린이가 바라고 꿈꾸는 놀이터를 만들기 위해 조성한 공간으로, 2019년 11월 개장했다.\n놀이터는 3개의 원형 모래놀이터로 구성되어 있으며, 세족장과 음수대, 공중화장실 등의 편의시설이 마련되어 있다. 원목 놀이기구와 천연목재 산책로, 황토 포장 등 자연 소재를 활용한 시설이 조성되어 있으며, 자연 지형과 주변 환경을 활용해 놀이공간을 구성했다.\n주요 놀이시설로 롱미끄럼틀과 집라인 등이 있으며, 관리사무실 앞에는 어린이 자전거와 모래놀이 도구가 마련되어 있다."}}}'
