SELECT 'tourapi-4025563', '신촌1번약국', '서대문구', 37.5555816888156, 126.93624390355, '서울특별시 서대문구 신촌로 89 (창천동) 1층', '38', '신촌1번약국은 신촌역 인근의 지리적 편리함과 전문적인 약료 서비스를 결합한 지역 최고의 건강 거점입니다. 풍부한 의약품 구비와 신속하고 정확한 조제를 통해 바쁜 현대인들의 건강을 책임지는 안심 약국입니다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/73/4045073_image2_1.JPG', '', 'TOURAPI', '4025563', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 신촌로 89 (창천동)","addr2":"1층","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"4025563","contenttypeid":"38","createdtime":"20260227100105","firstimage":"https://tong.visitkorea.or.kr/cms/resource/73/4045073_image2_1.JPG","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/73/4045073_image3_1.JPG","cpyrhtDivCd":"Type3","mapx":"126.93624390355","mapy":"37.5555816888156","mlevel":"","modifiedtime":"20260327092150","sigungucode":"","tel":"","title":"신촌1번약국","zipcode":"03789","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH04","lclsSystm3":"SH040300","detail":{"contentid":"4025563","contenttypeid":"38","title":"신촌1번약국","createdtime":"20260227100105","modifiedtime":"20260327092150","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/73/4045073_image2_1.JPG","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/73/4045073_image3_1.JPG","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH04","lclsSystm3":"SH040300","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 신촌로 89 (창천동)","addr2":"1층","zipcode":"03789","mapx":"126.93624390355","mapy":"37.5555816888156","mlevel":"","overview":"신촌1번약국은 신촌역 인근의 지리적 편리함과 전문적인 약료 서비스를 결합한 지역 최고의 건강 거점입니다. 풍부한 의약품 구비와 신속하고 정확한 조제를 통해 바쁜 현대인들의 건강을 책임지는 안심 약국입니다."}}}'
