SELECT 'tourapi-842887', '신촌고기창고', '서대문구', 37.5577888717855, 126.935009271806, '서울특별시 서대문구 연세로7길 34-4', '39', '고기창고의 돼지갈비는 글루코사민과 월계수, 타임, 오레가노, 로즈메리 등으로 숙성시켜 돼지고기 특유의 냄새도 나지 않는 것이 세련된 맛을 낸다. 노릇노릇 구워진 양념 갈빗살은 입안에서 씹힐새도 없이 사르르 녹는다. 엄선한 비법양념으로 고기도 질기지 않고 부드럽고 맛이 좋다. 이러한 고기창고는 각종 언론매체와 방송을 통해 보도 및 소개되었고, 정량을 지키면서 저렴한 가격으로 유명한 집이다.', 'https://www.data.go.kr/data/15101578/openapi.do', NULL, '', 'TOURAPI', '842887', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연세로7길 34-4","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"842887","contenttypeid":"39","createdtime":"20091029055445","firstimage":"","firstimage2":"","cpyrhtDivCd":"","mapx":"126.935009271806","mapy":"37.5577888717855","mlevel":"6","modifiedtime":"20260205142613","sigungucode":"","tel":"","title":"신촌고기창고","zipcode":"03788","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","detail":{"contentid":"842887","contenttypeid":"39","title":"신촌고기창고","createdtime":"20091029055445","modifiedtime":"20260205142613","tel":"","telname":"","homepage":"","firstimage":"","firstimage2":"","cpyrhtDivCd":"","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연세로7길 34-4","addr2":"","zipcode":"03788","mapx":"126.935009271806","mapy":"37.5577888717855","mlevel":"6","overview":"고기창고의 돼지갈비는 글루코사민과 월계수, 타임, 오레가노, 로즈메리 등으로 숙성시켜 돼지고기 특유의 냄새도 나지 않는 것이 세련된 맛을 낸다. 노릇노릇 구워진 양념 갈빗살은 입안에서 씹힐새도 없이 사르르 녹는다. 엄선한 비법양념으로 고기도 질기지 않고 부드럽고 맛이 좋다. 이러한 고기창고는 각종 언론매체와 방송을 통해 보도 및 소개되었고, 정량을 지키면서 저렴한 가격으로 유명한 집이다."}}}'
