INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-3317667', '신촌글로벌대학문화축제', '서대문구', 37.5567, 126.936775, '서울특별시 서대문구 창천동 연세로 스타광장', '15', '신촌글로벌대학문화축제는 청년도시 신촌의 글로벌 도시 브랜드 이미지를 구축하고, 신촌이 가진 ‘글로벌’과 ‘대학문화’의 아이덴티티를 축제로 구현한 서대문구의 대표 축제​이다. 젊음과 청춘이 세계 각국의 문화와 만나고, 다양한 글로벌 WAVE가 더해져 신촌만의 특별한 VIBE를 느낄 수 있는 다채로운 문화·체험 프로그램이 펼쳐진다. 축제 기간 동안 대학생들이 직접 기획하고 참여하는 다양한 프로그램을 비롯해 세계 각국의 문화를 만나볼 수 있는 글로벌 문화체험 부스, 각국의 특색 있는 음식을 맛볼 수 있는 세계음식 부스, 대학생들이 직접 운영하는 대학문화 부스 등이 신촌 연세로를 가득 채운다. 또한 메인무대에서는 대학생 공연과 참여형 프로그램, 글로벌 문화공연, 다양한 청춘 콘텐츠가 이어져 축제장을 찾은 시민과 국내외 청년들이 함께 즐기고 소통할 수 있는 시간을 제공한다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/60/4105960_image2_1.jpg', '', 'TOURAPI', '3317667', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 창천동","addr2":"연세로 스타광장","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"3317667","contenttypeid":"15","createdtime":"20240620135814","firstimage":"https://tong.visitkorea.or.kr/cms/resource/60/4105960_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/60/4105960_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9367750000","mapy":"37.5567000000","mlevel":"6","modifiedtime":"20260831142842","sigungucode":"","tel":"02-330-8108","title":"신촌글로벌대학문화축제","zipcode":"03785","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"EV","lclsSystm2":"EV01","lclsSystm3":"EV010200","detail":{"contentid":"3317667","contenttypeid":"15","title":"신촌글로벌대학문화축제","createdtime":"20240620135814","modifiedtime":"202608311