SELECT 'tourapi-2581396', '신촌문화발전소', '서대문구', 37.5579629643, 126.939755159, '서울특별시 서대문구 연세로2나길 57 (창천동)', '14', '신촌문화발전소는 청년 문화예술인의 창작활동을 지원하고 함께 성장하는 문화 예술 커뮤니티 공간이다. 약 80석 규모의 소극장과 창작기획 스튜디오 등을 갖춘 복합문화공간으로 예술인들이 모여 서로 나누고 협업할 수 있는 베이스캠프가 되고자 하며, 청년 예술인 스스로 가능성을 확장하고 성장할 수 있도록 기획과 창작, 발표의 과정을 지원하는 문화 예술 플랫폼을 지향한다. 신촌 지역의 특성을 살려 경계를 넘나드는 자유로운 상상과 창의적 실험이 다양하게 구현되는 기회를 마련하고 경쟁과 배제보다 교류와 협력을 통해 건강하고 안전한 창작 환경을 제공할 수 있도록 노력하는 공간이다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/74/3466974_image2_1.jpg', '', 'TOURAPI', '2581396', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연세로2나길 57 (창천동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2581396","contenttypeid":"14","createdtime":"20181221191029","firstimage":"https://tong.visitkorea.or.kr/cms/resource/74/3466974_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/74/3466974_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9397551590","mapy":"37.5579629643","mlevel":"6","modifiedtime":"20261001112100","sigungucode":"","tel":"","title":"신촌문화발전소","zipcode":"03777","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE06","lclsSystm3":"VE060100","detail":{"contentid":"2581396","contenttypeid":"14","title":"신촌문화발전소","createdtime":"20181221191029","modifiedtime":"20261001112100","tel":"","telname":"","homepage":"https://www.scas.or.kr/","firstimage":"https://tong.visitkorea.or.kr/cms/resourc