SELECT 'tourapi-2918764', '신촌수제비', '서대문구', 37.5558641301, 126.9363203098, '서울특별시 서대문구 신촌로 87-8 금은동빌딩', '39', '서대문구 창천동에 위치한 신촌수제비는 1988년에 오픈한 수제비 전문점이다. 별다른 메뉴 없이 수제비와 김밥, 단 두 가지 메뉴만 취급한다. 수제비는 진한 사골 국물에 볶은 호박과 당근, 다진 고기를 고명으로 올려낸다. 어디에나 곁들여 먹기 좋은 김밥도 인기이다. 식사 시간에는 인기 있는 가게인 만큼 줄을 기다려야 한다. 가성비 있는 맛집으로 유명한 곳이다.', 'https://www.data.go.kr/data/15101578/openapi.do', NULL, '', 'TOURAPI', '2918764', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 신촌로 87-8 금은동빌딩","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2918764","contenttypeid":"39","createdtime":"20221124175258","firstimage":"","firstimage2":"","cpyrhtDivCd":"","mapx":"126.9363203098","mapy":"37.5558641301","mlevel":"6","modifiedtime":"20260630101954","sigungucode":"","tel":"","title":"신촌수제비","zipcode":"03789","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","detail":{"contentid":"2918764","contenttypeid":"39","title":"신촌수제비","createdtime":"20221124175258","modifiedtime":"20260630101954","tel":"","telname":"","homepage":"","firstimage":"","firstimage2":"","cpyrhtDivCd":"","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 신촌로 87-8 금은동빌딩","addr2":"","zipcode":"03789","mapx":"126.9363203098","mapy":"37.5558641301","mlevel":"6","overview":"서대문구 창천동에 위치한 신촌수제비는 1988년에 오픈한 수제비 전문점이다. 별다른 메뉴 없이 수제비와 김밥, 단 두 가지 메뉴만 취급한다. 수제비는 진한 사골 국물에 볶은 호박과 당근, 다진 고기를 고명으로 올려낸다. 어디에나 곁들여 먹기 좋은 김밥도 인기이다. 식사 시간에는 인기 있는 가게인 만큼 줄을 기다려야 한다. 가성비 있는 맛집으로 유명한 곳이다."}}}'
