SELECT 'tourapi-2853867', '엄마손떡볶이', '서대문구', 37.5789907137, 126.9241617334, '서울특별시 서대문구 증가로10길 37', '39', '증산역과 가좌역에서 차로 7분 정도 거리에 있는 40년 전통의 떡볶이 전문점이다. 명지대학교 정문 건너편 샛길로 들어가면 왼쪽 모퉁이에 위치해 있다. 대표 메뉴는 떡볶이로, 이 외에도 순대와 어묵, 라면, 쫄면, 냉면 등 다양한 분식 메뉴를 맛볼 수 있다. 넓고 정겨운 분위기의 내부에서 식사가 가능하다. 차량으로 15~20분 거리에 망원시장과 망원한강공원 등이 있어서 관광하기 좋다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'http://tong.visitkorea.or.kr/cms/resource/56/2853856_image2_1.jpg', '', 'TOURAPI', '2853867', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 증가로10길 37","addr2":"","areacode":"1","cat1":"A05","cat2":"A0502","cat3":"A05020100","contentid":"2853867","contenttypeid":"39","createdtime":"20220915133657","firstimage":"http://tong.visitkorea.or.kr/cms/resource/56/2853856_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/56/2853856_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9241617334","mapy":"37.5789907137","mlevel":"6","modifiedtime":"20250117102650","sigungucode":"14","tel":"","title":"엄마손떡볶이","zipcode":"03665","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD03","lclsSystm3":"FD030400","detail":{"contentid":"2853867","contenttypeid":"39","title":"엄마손떡볶이","createdtime":"20220915133657","modifiedtime":"20250117102650","tel":"","telname":"","homepage":"","firstimage":"http://tong.visitkorea.or.kr/cms/resource/56/2853856_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/56/2853856_image3_1.jpg","cpyrhtDivCd":"T