SELECT 'tourapi-2938584', '에버그린', '서대문구', 37.5809943807248, 126.935325246804, '서울특별시 서대문구 모래내로 350', '39', '에버그린은 점심에는 경양식집으로 운영되고 있으며, 저녁에는 호프집으로 운영한다. 옛날 그대로 추억의 경양식을 맛볼 수 있는 곳이다. 가성비가 좋으면서 항상 시원한 미역국과 잘 익은 오이소박이와 깍두기가 나오는 곳이다. 그 외 수프도 직접 만든 수제 수프이다. 메뉴는 돈가스, 생선가스, 햄버그스테이크 외에도 오므라이스, 김치볶음밥, 제육덮밥 등을 판매한다. 가장 좋은 점은 한 가지 메뉴만 먹을 수 있는 것이 아닌 에버그린정식(햄버그스테이크, 돈가스, 생선가스)을 저렴하게 판매하고 있어 다양한 맛을 맛볼 수 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', NULL, '', 'TOURAPI', '2938584', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 모래내로 350","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2938584","contenttypeid":"39","createdtime":"20221222142551","firstimage":"","firstimage2":"","cpyrhtDivCd":"","mapx":"126.935325246804","mapy":"37.5809943807248","mlevel":"6","modifiedtime":"20260312172045","sigungucode":"","tel":"","title":"에버그린","zipcode":"03658","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","detail":{"contentid":"2938584","contenttypeid":"39","title":"에버그린","createdtime":"20221222142551","modifiedtime":"20260312172045","tel":"","telname":"","homepage":"","firstimage":"","firstimage2":"","cpyrhtDivCd":"","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 모래내로 350","addr2":"","zipcode":"03658","mapx":"126.935325246804","mapy":"37.5809943807248","mlevel":"6","overview":"에버그린은 점심에는 경양식집으로 운영되고 있으며, 저녁에는 호프집으로 운영한다. 옛날 그대로 추억의 경양식을 맛볼 수 있는 곳이다. 가성비가 좋으면서 항상 시원한 미역국과 잘 익은 오이소박이와 깍두기가 나오는 곳이다. 그 외 수프도 직접 만든 수제 수프이다. 메뉴는 돈가스, 생선가스, 햄버그스테이크 외에도 오므라이스, 김치볶음밥, 제육덮밥 등을 판매한다. 가장 좋은 점은 한 가지 메뉴만 먹을 수 있는 것이 아닌 에버그린정식(햄버그스테이크, 돈가스, 생선가스)을 저렴하게 판매하고 있어 다양한 맛을 맛볼 수 있다."}}}'
