INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-2914737', '연남장', '서대문구', 37.56433121474035, 126.92758581262362, '서울특별시 서대문구 연희로5길 22 (연희동) 1층', '39', '연남장은 서대문구 연희동에 위치한 브런치 카페로, 감각적인 공간과 여유로운 분위기 속에서 식사를 즐길 수 있는 곳이다. 넓고 깔끔한 내부는 편안한 분위기로 꾸며져 있어 브런치와 커피를 즐기며 여유로운 시간을 보내기 좋다. 샌드위치와 파스타, 브런치 메뉴를 비롯해 다양한 음료와 디저트도 함께 제공하고 있으며, 매장 앞 무료 주차 공간이 마련되어 있어 차량으로 방문하기 편리하다. 또한 도보 10분 거리에는 경의선 숲길 공원이 있어 식사 후 산책을 즐기기 좋으며, 주변에는 개성 있는 디저트 카페와 갤러리, 독립서점 등이 자리하고 있어 연희동 감성을 함께 느끼기 좋다. 편안한 분위기와 감각적인 공간, 연희동 특유의 여유로운 매력을 함께 즐길 수 있는 브런치 카페이다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/02/4067302_image2_1.jpg', '', 'TOURAPI', '2914737', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희로5길 22 (연희동)","addr2":"1층","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2914737","contenttypeid":"39","createdtime":"20221122110707","firstimage":"https://tong.visitkorea.or.kr/cms/resource/02/4067302_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/02/4067302_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.92758581262362","mapy":"37.56433121474035","mlevel":"6","modifiedtime":"20260522144429","sigungucode":"","tel":"","title":"연남장","zipcode":"03716","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD05","lclsSystm3":"FD050100","detail":{"contentid":"2914737","contenttypeid":"39","title":"연남장","createdtime":"20221122110707","modifiedtime":"20260522144429","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/02/4067302_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/02/4067302_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD05","lclsSystm3":"FD050100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연희로5길 22 (연희동)","addr2":"1층","zipcode":"03716","mapx":"126.92758581262362","mapy":"37.56433121474035","mlevel":"6","overview":"연남장은 서대문구 연희동에 위치한 브런치 카페로, 감각적인 공간과 여유로운 분위기 속에서 식사를 즐길 수 있는 곳이다. 넓고 깔끔한 내부는 편안한 분위기로 꾸며져 있어 브런치와 커피를 즐기며 여유로운 시간을 보내기 좋다. 샌드위치와 파스타, 브런치 메뉴를 비롯해 다양한 음료와 디저트도 함께 제공하고 있으며, 매장 앞 무료 주차 공간이 마련되어 있어 차량으로 방문하기 편리하다. 또한 도보 10분 거리에는 경의선 숲길 공원이 있어 식사 후 산책을 즐기기 좋으며, 주변에는 개성 있는 디저트 카페와 갤러리, 독립서점 등이 자리하고 있어 연희동 감성을 함께 느끼기 좋다. 편안한 분위기와 감각적인 공간, 연희동 특유의 여유로운 매력을 함께 즐길 수 있는 브런치 카페이다."}}}'
