INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-264375', '연세로', '서대문구', 37.5557797448, 126.9365529264, '서울특별시 서대문구 연세로 일대', '12', '지하철 2호선 신촌역에서 연세대학교까지 이어지는 연세로는 신촌의 중심거리이다. 이 길을 중심으로 사잇길이 뿌리처럼 뻗어 있다. 연세로는 1999년 서울시가 걷고 싶은 거리로 지정한 이후 가로수 정비, 신촌거리 지도 부착 등의 조성사업을 했다. 학생, 아마추어 아티스트들의 다양한 재량을 발휘할 수 있는 거리공연이 열리고 있어 젊음과 활기가 넘치는 광장 같은 길이다. 각종 음식점, 패스트푸드점, 커피숍, 상점 등이 포진하고 있으며 오후가 되면 길거리 음식도 맛볼 수 있다. 연세대학교 도로 맞은편에는 아름다운 벽화가 그려져 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'http://tong.visitkorea.or.kr/cms/resource/73/3466373_image2_1.jpg', '', 'TOURAPI', '264375', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연세로 일대","addr2":"","areacode":"1","cat1":"A02","cat2":"A0203","cat3":"A02030600","contentid":"264375","contenttypeid":"12","createdtime":"20030814231500","firstimage":"http://tong.visitkorea.or.kr/cms/resource/73/3466373_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/73/3466373_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9365529264","mapy":"37.5557797448","mlevel":"6","modifiedtime":"20251105100417","sigungucode":"14","tel":"","title":"연세로","zipcode":"03789","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE04","lclsSystm3":"VE040100","detail":{"contentid":"264375","contenttypeid":"12","title":"연세로","createdtime":"20030814231500","modifiedtime":"20251105100417","tel":"","telname":"","homepage":"<a href=\"https://www.sdm.go.kr/culture/attraction/sub2050.do\" target=\"_blank\" title=\"새창: 서대문구 문화관광 홈페이지로 이동\">https://www.sdm.go.kr/culture/</a>","firstimage":"http://tong.visitkorea.or.kr/cms/resource/73/3466373_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/73/3466373_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"1","sigungucode":"14","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE04","lclsSystm3":"VE040100","cat1":"A02","cat2":"A0203","cat3":"A02030600","addr1":"서울특별시 서대문구 연세로 일대","addr2":"","zipcode":"03789","mapx":"126.9365529264","mapy":"37.5557797448","mlevel":"6","overview":"지하철 2호선 신촌역에서 연세대학교까지 이어지는 연세로는 신촌의 중심거리이다. 이 길을 중심으로 사잇길이 뿌리처럼 뻗어 있다. 연세로는 1999년 서울시가 걷고 싶은 거리로 지정한 이후 가로수 정비, 신촌거리 지도 부착 등의 조성사업을 했다. 학생, 아마추어 아티스트들의 다양한 재량을 발휘할 수 있는 거리공연이 열리고 있어 젊음과 활기가 넘치는 광장 같은 길이다. 각종 음식점, 패스트푸드점, 커피숍, 상점 등이 포진하고 있으며 오후가 되면 길거리 음식도 맛볼 수 있다. 연세대학교 도로 맞은편에는 아름다운 벽화가 그려져 있다."}}}'
WHERE NOT EXISTS (SELECT 1 FROM catalog_place WHERE id = 'tourapi-264375');

INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-2853889', '연희김밥 본점', '서대문구', 37.568026759, 126.9293758776, '서울특별시 서대문구 연희로11가길 2 (연희동)', '39', '연희동에 있는 김밥 전문점이로 가좌역과 홍대입구역에서 차량으로 5분 정도 거리에 있다. 도보로는 20분 이상 걸리기 때문에 차를 가지고 방문하거나 버스를 이용하는 것이 좋다. 연희김밥이 대표메뉴이고 특히 매운 오징어 김밥이 인기 있다. 그 외에도 멸치 김밥, 참치김밥, 장조림 김밥, 오징어 김밥, 꼬마김밥 등 다양한 종류의 김밥을 맛볼 수 있다. 근처에 갤러리, 전시관, 공원 등의 문화공간이 많아서 둘러보기 좋고 연세대학교, 서강대학교, 이화여자대학교 등의 학교들과 가깝다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/78/2853878_image2_1.jpg', '', 'TOURAPI', '2853889', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희로11가길 2 (연희동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2853889","contenttypeid":"39","createdtime":"20220915134142","firstimage":"https://tong.visitkorea.or.kr/cms/resource/78/2853878_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/78/2853878_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9293758776","mapy":"37.5680267590","mlevel":"6","modifiedtime":"20260930170430","sigungucode":"","tel":"","title":"연희김밥 본점","zipcode":"03707","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD03","lclsSystm3":"FD030400","detail":{"contentid":"2853889","contenttypeid":"39","title":"연희김밥 본점","createdtime":"20220915134142","modifiedtime":"20260930170430","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/78/2853878_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/78/2853878_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD03","lclsSystm3":"FD030400","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연희로11가길 2 (연희동)","addr2":"","zipcode":"03707","mapx":"126.9293758776","mapy":"37.5680267590","mlevel":"6","overview":"연희동에 있는 김밥 전문점이로 가좌역과 홍대입구역에서 차량으로 5분 정도 거리에 있다. 도보로는 20분 이상 걸리기 때문에 차를 가지고 방문하거나 버스를 이용하는 것이 좋다. 연희김밥이 대표메뉴이고 특히 매운 오징어 김밥이 인기 있다. 그 외에도 멸치 김밥, 참치김밥, 장조림 김밥, 오징어 김밥, 꼬마김밥 등 다양한 종류의 김밥을 맛볼 수 있다. 근처에 갤러리, 전시관, 공원 등의 문화공간이 많아서 둘러보기 좋고 연세대학교, 서강대학교, 이화여자대학교 등의 학교들과 가깝다."}}}'
