INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-3544787', '연희숲속쉼터', '서대문구', 37.5804, 126.9386, '서울특별시 서대문구 연희동', '12', '연희숲속쉼터는 서대문구청 뒤의 청소년 수련관 옆 서대문안산 기슭에 위치한 쉼터로 도심 속에서 자연을 느낄 수 있는 공간이다. 매년 봄 화려한 벗꽃들이 아름다운 명소로도 유명하다. 쉼터에는 허브정원과 벚꽃마당, 숲속 쉼터, 잔디 마당 등 들르는 사람들의 마음을 사로잡는 장소들이 마련되어 있다. 워낙 다채롭고 아름다운 볼거리가 가득하여 계절에 상관없이 많은 사람들이 찾고 있으며, 특히 봄에 가족, 친구, 연인과 함께 벚꽃을 보며 추억을 남기기에도 좋다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/71/3544771_image2_1.jpg', '', 'TOURAPI', '3544787', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희동","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"3544787","contenttypeid":"12","createdtime":"20250926133127","firstimage":"https://tong.visitkorea.or.kr/cms/resource/71/3544771_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/71/3544771_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9386","mapy":"37.5804","mlevel":"6","modifiedtime":"20260407095254","sigungucode":"","tel":"","title":"연희숲속쉼터","zipcode":"03726","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"NA","lclsSystm2":"NA05","lclsSystm3":"NA050100","detail":{"contentid":"3544787","contenttypeid":"12","title":"연희숲속쉼터","createdtime":"20250926133127","modifiedtime":"20260407095254","tel":"","telname":"","homepage":"https://www.sdm.go.kr/culture/","firstimage":"https://tong.visitkorea.or.kr/cms/resource/71/3544771_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/71/3544771_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"NA","lclsSystm2":"NA05","lclsSystm3":"NA050100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연희동","addr2":"","zipcode":"03726","mapx":"126.9386","mapy":"37.5804","mlevel":"6","overview":"연희숲속쉼터는 서대문구청 뒤의 청소년 수련관 옆 서대문안산 기슭에 위치한 쉼터로 도심 속에서 자연을 느낄 수 있는 공간이다. 매년 봄 화려한 벗꽃들이 아름다운 명소로도 유명하다. 쉼터에는 허브정원과 벚꽃마당, 숲속 쉼터, 잔디 마당 등 들르는 사람들의 마음을 사로잡는 장소들이 마련되어 있다. 워낙 다채롭고 아름다운 볼거리가 가득하여 계절에 상관없이 많은 사람들이 찾고 있으며, 특히 봄에 가족, 친구, 연인과 함께 벚꽃을 보며 추억을 남기기에도 좋다."}}}'
