SELECT 'tourapi-4013027', '오렌즈 현대백화점 신촌점', '서대문구', 37.5560830579515, 126.935844876509, '서울특별시 서대문구 신촌로 83 (창천동) B2층', '38', '오렌즈는 한국의 컬러렌즈 브랜드입니다. 다양한 컬러와 트렌디한 디자인으로 자연스러운 눈매 연출이 가능합니다. 안전한 품질과 편안한 착용감으로 전 세계에서 사랑받고 있습니다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/69/4023869_image2_1.jpg', '', 'TOURAPI', '4013027', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 신촌로 83 (창천동)","addr2":"B2층","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"4013027","contenttypeid":"38","createdtime":"20260207120004","firstimage":"https://tong.visitkorea.or.kr/cms/resource/69/4023869_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/69/4023869_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.935844876509","mapy":"37.5560830579515","mlevel":"","modifiedtime":"20260330091611","sigungucode":"","tel":"","title":"오렌즈 현대백화점 신촌점","zipcode":"03789","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH04","lclsSystm3":"SH040300","detail":{"contentid":"4013027","contenttypeid":"38","title":"오렌즈 현대백화점 신촌점","createdtime":"20260207120004","modifiedtime":"20260330091611","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/69/4023869_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/69/4023869_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":