SELECT 'tourapi-2927075', '올젠 현대백화점 신촌점', '서대문구', 37.5560830579515, 126.935844876509, '서울특별시 서대문구 신촌로 83 (창천동)', '38', '올젠은 자연스러움과 품격을 담은 남성복 브랜드로, 편안함과 세련된 디자인을 동시에 제공합니다. 고품질 소재와 섬세한 마감으로 완성된 의류는 도시적 감성과 여유로운 라이프스타일을 반영하며, 실용적이면서도 스타일리시한 남성 패션을 제안합니다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/46/4019946_image2_1.jpg', '', 'TOURAPI', '2927075', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 신촌로 83 (창천동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2927075","contenttypeid":"38","createdtime":"20221030230103","firstimage":"https://tong.visitkorea.or.kr/cms/resource/46/4019946_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/46/4019946_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.935844876509","mapy":"37.5560830579515","mlevel":"6","modifiedtime":"20260327092150","sigungucode":"","tel":"","title":"올젠 현대백화점 신촌점","zipcode":"03789","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH04","lclsSystm3":"SH040300","detail":{"contentid":"2927075","contenttypeid":"38","title":"올젠 현대백화점 신촌점","createdtime":"20221030230103","modifiedtime":"20260327092150","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/46/4019946_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/46/4019946_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongS