INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-134708', '완차이', '서대문구', 37.5587127872, 126.9393525884, '서울특별시 서대문구 명물길 50-7', '39', '서울시 서대문구 창천동에 위치한 중식당이다. 처음 개업할 때 신촌의 허름한 뒷골목에 위치했으며, 한국인의 입맛을 자극하는 매운 홍합요리로 입소문을 타고 유명해진 곳이다. 완차이라는 식당 이름은 매운 중국음식점이라 표방한 것인데, 매운맛을 좋아하는 사람이라면 꼭 한 번쯤 찾아갈 만한 곳이다. 중국 쓰촨성에서 맛본 정통의 매운맛이라기보다는 한국식 매운맛이 가미되어 오히려 중국 정통 사천요리보다 더 맛이 좋다. 완차이는 이미 많은 입소문을 타서 인지, 항상 자리가 차 있어서 20분은 족히 기다려야 음식들과 만날 수가 있다. 가장 인기가 있는 것은 아주 매운 홍합 볶음. 빨간 실내 분위기와 큰 접시 위의 빨간 홍합 볶음을 여기저기에서 볼 수가 있다. 홍합을 마른 홍고추와 마늘, 그리고 매운 소스로 볶은 것이다. 굴짬뽕 또한 얼큰하고 시원한 맛에 사람들이 자주 찾는다. 또한 이 집은 기본적으로 자장면도 맛있다. 까만 자장소스가 깔끔하고 고소하다.', 'https://www.data.go.kr/data/15101578/openapi.do', NULL, '', 'TOURAPI', '134708', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 명물길 50-7","addr2":"","areacode":"1","cat1":"A05","cat2":"A0502","cat3":"A05020400","contentid":"134708","contenttypeid":"39","createdtime":"20041129090000","firstimage":"","firstimage2":"","cpyrhtDivCd":"","mapx":"126.9393525884","mapy":"37.5587127872","mlevel":"6","modifiedtime":"20251212152501","sigungucode":"14","tel":"","title":"완차이","zipcode":"03777","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020100","detail":{"contentid":"134708","contenttypeid":"39","title":"완차이","createdtime":"20041129090000","modifiedtime":"20251212152501","tel":"","telname":"","homepage":"","firstimage":"","firstimage2":"","cpyrhtDivCd":"","areacode":"1","sigungucode":"14","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020100","cat1":"A05","cat2":"A0502","cat3":"A05020400","addr1":"서울특별시 서대문구 명물길 50-7","addr2":"","zipcode":"03777","mapx":"126.9393525884","mapy":"37.5587127872","mlevel":"6","overview":"서울시 서대문구 창천동에 위치한 중식당이다. 처음 개업할 때 신촌의 허름한 뒷골목에 위치했으며, 한국인의 입맛을 자극하는 매운 홍합요리로 입소문을 타고 유명해진 곳이다. 완차이라는 식당 이름은 매운 중국음식점이라 표방한 것인데, 매운맛을 좋아하는 사람이라면 꼭 한 번쯤 찾아갈 만한 곳이다. 중국 쓰촨성에서 맛본 정통의 매운맛이라기보다는 한국식 매운맛이 가미되어 오히려 중국 정통 사천요리보다 더 맛이 좋다. 완차이는 이미 많은 입소문을 타서 인지, 항상 자리가 차 있어서 20분은 족히 기다려야 음식들과 만날 수가 있다. 가장 인기가 있는 것은 아주 매운 홍합 볶음. 빨간 실내 분위기와 큰 접시 위의 빨간 홍합 볶음을 여기저기에서 볼 수가 있다. 홍합을 마른 홍고추와 마늘, 그리고 매운 소스로 볶은 것이다. 굴짬뽕 또한 얼큰하고 시원한 맛에 사람들이 자주 찾는다. 또한 이 집은 기본적으로 자장면도 맛있다. 까만 자장소스가 깔끔하고 고소하다."}}}'
WHERE NOT EXISTS (SELECT 1 FROM catalog_place WHERE id = 'tourapi-134708');

