SELECT 'tourapi-2553390', '우석뮤지엄', '서대문구', 37.5566186049, 126.9403997739, '서울특별시 서대문구 신촌로 129 (창천동) 5층', '14', '우석뮤지엄은 전각가이자 서예가인 우석 최규명 선생(1919~1999)의 작고 15주기를 맞아 2014년 2월 우석의 서예작품을 만날 수 있는 갤러리충과 함께 개관하였다. 우석뮤지엄에는 우석선생의 전각작품 450 여과가 전시되고 있으며, 선생이 즐겨 쓰던 문방사우와 선생이 수집한 고미술품이 함께 전시되어 있다. 선생의 서예작품이 전시된 갤러리충에서는 1000여 점이 넘는 서예작품을 교체 전시하고 있으며, 다양한 기획전시를 통해 전각과 서예가 현대미술과 어떤 연관을 가지고 발전하고 있는지를 알리는 데 역할을 하고 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'http://tong.visitkorea.or.kr/cms/resource/84/3502784_image2_1.jpg', '', 'TOURAPI', '2553390', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 신촌로 129 (창천동)","addr2":"5층","areacode":"1","cat1":"A02","cat2":"A0206","cat3":"A02060100","contentid":"2553390","contenttypeid":"14","createdtime":"20180711232334","firstimage":"http://tong.visitkorea.or.kr/cms/resource/84/3502784_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/84/3502784_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9403997739","mapy":"37.5566186049","mlevel":"6","modifiedtime":"20250707101113","sigungucode":"14","tel":"","title":"우석뮤지엄","zipcode":"03780","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE07","lclsSystm3":"VE070100","detail":{"contentid":"2553390","contenttypeid":"14","title":"우석뮤지엄","createdtime":"20180711232334","modifiedtime":"20250707101113","tel":"","telname":"","homepage":"","firstimage":"http://tong.visitkorea.or.kr/cms/resource/84/3502784_image2_1.jpg","firstimage2