SELECT 'tourapi-3306578', '원더플레이스 현대백화점 신촌점 유플렉스', '서대문구', 37.5567378385686, 126.936559696179, '서울특별시 서대문구 연세로 13 (창천동)', '38', '원더플레이스는 국내외 핫한 스트릿 브랜드와 신진 디자이너 브랜드를 한데 모은 라이프스타일 편집 브랜드입니다. 유니크한 패션 아이템부터 소품까지, 즐거운 놀이터처럼 개성 넘치는 쇼핑 경험을 선사합니다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/44/4042044_image2_1.jpg', '', 'TOURAPI', '3306578', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연세로 13 (창천동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"3306578","contenttypeid":"38","createdtime":"20240202190807","firstimage":"https://tong.visitkorea.or.kr/cms/resource/44/4042044_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/44/4042044_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.936559696179","mapy":"37.5567378385686","mlevel":"6","modifiedtime":"20260326092041","sigungucode":"","tel":"","title":"원더플레이스 현대백화점 신촌점 유플렉스","zipcode":"03789","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH04","lclsSystm3":"SH040300","detail":{"contentid":"3306578","contenttypeid":"38","title":"원더플레이스 현대백화점 신촌점 유플렉스","createdtime":"20240202190807","modifiedtime":"20260326092041","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/44/4042044_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/44/4042044_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","l