SELECT 'tourapi-2817140', '위고인호스텔', '서대문구', 37.556862696, 126.9415741634, '서울특별시 서대문구 신촌로 141 (대현동)', '32', '위고인 호스텔은 합리적인 가격으로 최고의 서비스와 편안한 숙박을 제공한다. 지하철 2호선 신촌역에서 도보 6분, 2호선 이대역에서 도보 4분 거리에 위치해 있다. 여행을 더욱 풍요롭게 만들기 위해 깨끗하고 모던한 객실을 갖추고 있으며 대학가의 감성, 젊은 활기가 넘치는 위고인 호스텔에서 서울의 낮과 밤을 즐겨볼 수 있다. 편안한 분위기의 카페와 서울의 야경을 즐길 수 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/83/4119083_image2_1.jpg', '', 'TOURAPI', '2817140', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 신촌로 141 (대현동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2817140","contenttypeid":"32","createdtime":"20220422163424","firstimage":"https://tong.visitkorea.or.kr/cms/resource/83/4119083_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/83/4119083_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9415741634","mapy":"37.5568626960","mlevel":"6","modifiedtime":"20261007154440","sigungucode":"","tel":"","title":"위고인호스텔","zipcode":"03780","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"AC","lclsSystm2":"AC01","lclsSystm3":"AC010100","detail":{"contentid":"2817140","contenttypeid":"32","title":"위고인호스텔","createdtime":"20220422163424","modifiedtime":"20261007154440","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/83/4119083_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/83/4119083_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"AC","lclsSystm2":"AC01","lclsSystm3":"AC010100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 신촌로 141 (대현동)","addr2":"","zipcode":"03780","mapx":"126.9415741634","mapy":"37.5568626960","mlevel":"6","overview":"위고인 호스텔은 합리적인 가격으로 최고의 서비스와 편안한 숙박을 제공한다. 지하철 2호선 신촌역에서 도보 6분, 2호선 이대역에서 도보 4분 거리에 위치해 있다. 여행을 더욱 풍요롭게 만들기 위해 깨끗하고 모던한 객실을 갖추고 있으며 대학가의 감성, 젊은 활기가 넘치는 위고인 호스텔에서 서울의 낮과 밤을 즐겨볼 수 있다. 편안한 분위기의 카페와 서울의 야경을 즐길 수 있다."}}}'
