SELECT 'tourapi-2044896', '유어마인드', '서대문구', 37.5683972902, 126.9303034443, '서울특별시 서대문구 연희로11라길 10-6 (연희동) 302호', '14', '콘텐츠 제작부터 출간, 유통까지 한 사람의 손길을 거쳐 나오는 책이 독립출판물이다. 유어마인드는 독립출판물을 만나볼 수 있는 서점이다. 2009년부터 작가 개인과 독립출판사에 의해 제작된 독립출판물과 아트북을 전문으로 판매하고 있다. 동시에 자체 출판물을 제작하고 서울아트북페어 ‘언리미티드 에디션’을 매년 주최하고 있다. 독립출판 도서는 일반 서적들과는 성향이 달라 대형서점에서는 만나기 쉽지 않은데, 유어마인드에서는 이러한 도서들을 만나볼 수 있다. 내부는 다락방처럼 보이는 서가와 작은 매대, 책상 등으로 꾸며져 있으며, 매장 이외에 홈페이지를 통해 구매가 가능하다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/66/4107066_image2_1.JPG', '', 'TOURAPI', '2044896', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희로11라길 10-6 (연희동)","addr2":"302호","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2044896","contenttypeid":"14","createdtime":"20151202195740","firstimage":"https://tong.visitkorea.or.kr/cms/resource/66/4107066_image2_1.JPG","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/66/4107066_image3_1.JPG","cpyrhtDivCd":"Type3","mapx":"126.9303034443","mapy":"37.5683972902","mlevel":"6","modifiedtime":"20260902174537","sigungucode":"","tel":"","title":"유어마인드","zipcode":"03703","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE12","lclsSystm3":"VE120100","detail":{"contentid":"2044896","contenttypeid":"14","title":"유어마인드","createdtime":"20151202195740","modifiedtime":"20260902174537","tel":"","telname":"","homepage":"공식 홈페이지 http://www.your-mind.com공식 인스타그램 https://www.instagram.com/your_mind_com","firstimage":"https://tong.visitkorea.or.kr/cms/resource/66/4107066_image2_1.JPG","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/66/4107066_image3_1.JPG","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE12","lclsSystm3":"VE120100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연희로11라길 10-6 (연희동)","addr2":"302호","zipcode":"03703","mapx":"126.9303034443","mapy":"37.5683972902","mlevel":"6","overview":"콘텐츠 제작부터 출간, 유통까지 한 사람의 손길을 거쳐 나오는 책이 독립출판물이다. 유어마인드는 독립출판물을 만나볼 수 있는 서점이다. 2009년부터 작가 개인과 독립출판사에 의해 제작된 독립출판물과 아트북을 전문으로 판매하고 있다. 동시에 자체 출판물을 제작하고 서울아트북페어 ‘언리미티드 에디션’을 매년 주최하고 있다. 독립출판 도서는 일반 서적들과는 성향이 달라 대형서점에서는 만나기 쉽지 않은데, 유어마인드에서는 이러한 도서들을 만나볼 수 있다. 내부는 다락방처럼 보이는 서가와 작은 매대, 책상 등으로 꾸며져 있으며, 매장 이외에 홈페이지를 통해 구매가 가능하다."}}}'
