SELECT 'tourapi-2759917', '은가어린이공원', '서대문구', 37.5827, 126.9195, '서울특별시 서대문구 북가좌동', '12', '은가어린이공원은 서울 서대문구 북가좌동의 주택가 중심에 위치한 소규모 공원이다. 규모는 크지 않지만 아기자기하게 잘 조성되어 있어 인근 주민들과 아이들에게 인기 있는 공원이다. 여름철이 되면 공원 내 수경시설이 가동되어 아이들이 시원하게 물놀이를 즐길 수 있는 물놀이터로 변신한다. 공원에는 화장실과 탈의실도 설치되어 있어 아이들과 함께 방문한 보호자들이 편리하게 이용할 수 있다. 지역 주민들의 생활 속 쉼터로도 기능하고 있으며 아침과 저녁 시간대에는 산책을 하거나 가볍게 운동을 즐기기 좋은 공간이다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/53/3509953_image2_1.jpg', '', 'TOURAPI', '2759917', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 북가좌동","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2759917","contenttypeid":"12","createdtime":"20211020225155","firstimage":"https://tong.visitkorea.or.kr/cms/resource/53/3509953_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/53/3509953_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9195","mapy":"37.5827","mlevel":"6","modifiedtime":"20260312125446","sigungucode":"","tel":"","title":"은가어린이공원","zipcode":"03714","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE03","lclsSystm3":"VE030300","detail":{"contentid":"2759917","contenttypeid":"12","title":"은가어린이공원","createdtime":"20211020225155","modifiedtime":"20260312125446","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/53/3509953_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/53/3509953_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE03","lclsSystm3":"VE030300","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 북가좌동","addr2":"","zipcode":"03714","mapx":"126.9195","mapy":"37.5827","mlevel":"6","overview":"은가어린이공원은 서울 서대문구 북가좌동의 주택가 중심에 위치한 소규모 공원이다. 규모는 크지 않지만 아기자기하게 잘 조성되어 있어 인근 주민들과 아이들에게 인기 있는 공원이다. 여름철이 되면 공원 내 수경시설이 가동되어 아이들이 시원하게 물놀이를 즐길 수 있는 물놀이터로 변신한다. 공원에는 화장실과 탈의실도 설치되어 있어 아이들과 함께 방문한 보호자들이 편리하게 이용할 수 있다. 지역 주민들의 생활 속 쉼터로도 기능하고 있으며 아침과 저녁 시간대에는 산책을 하거나 가볍게 운동을 즐기기 좋은 공간이다."}}}'
