INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-2667611', '이대거리', '서대문구', 37.557877884, 126.9424446549, '서울특별시 서대문구 대현동', '12', '이화여대 정문에서 신촌 기차역까지 사이사이 이어지는 골목거리이다. 패션산업 부진으로 한때 공실이 많았으나 2017년 청년창업가 중심의 감각 있는 점포가 입점하기 시작하면서 되살아난 골목이다. 테이크아웃 가능한 카페 및 작은 음식점이 골목골목 이어져 있고 패션의 메카답게 의류, 미용실, 화장품, 구두, 액세서리, 네일숍 등 특색 있는 점포들로 볼거리가 풍부하다. (출처 : 서대문구청 홈페이지)', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/29/3467629_image2_1.jpg', '', 'TOURAPI', '2667611', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 대현동","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2667611","contenttypeid":"12","createdtime":"20200818233748","firstimage":"https://tong.visitkorea.or.kr/cms/resource/29/3467629_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/29/3467629_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9424446549","mapy":"37.5578778840","mlevel":"6","modifiedtime":"20261020142812","sigungucode":"","tel":"","title":"이대거리","zipcode":"03767","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE04","lclsSystm3":"VE040100","detail":{"contentid":"2667611","contenttypeid":"12","title":"이대거리","createdtime":"20200818233748","modifiedtime":"20261020142812","tel":"","telname":"","homepage":"https://www.sdm.go.kr/culture/index.do","firstimage":"https://tong.visitkorea.or.kr/cms/resource/29/3467629_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/29/3467629_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE04","lclsSystm3":"VE040100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 대현동","addr2":"","zipcode":"03767","mapx":"126.9424446549","mapy":"37.5578778840","mlevel":"6","overview":"이화여대 정문에서 신촌 기차역까지 사이사이 이어지는 골목거리이다. 패션산업 부진으로 한때 공실이 많았으나 2017년 청년창업가 중심의 감각 있는 점포가 입점하기 시작하면서 되살아난 골목이다. 테이크아웃 가능한 카페 및 작은 음식점이 골목골목 이어져 있고 패션의 메카답게 의류, 미용실, 화장품, 구두, 액세서리, 네일숍 등 특색 있는 점포들로 볼거리가 풍부하다. \n\n(출처 : 서대문구청 홈페이지)"}}}'
