INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-130949', '이화여대 자연사박물관', '서대문구', 37.5617080471, 126.9465802534, '서울특별시 서대문구 이화여대길 52', '14', '이화여자대학교 자연사박물관은 자연에 대한 학교교육과 사회교육에 이바지할 목적으로 1969년 11월 20일 국내 최초로 설립되었다. 자연사박물관은 동물, 식물, 광물, 암석, 화석의 다양한 표본들과 실제 자연 생태계를 재현해 놓은 디오라마 전시, 살아있는 동물을 관찰할 수 있는 생태 코너, 자연환경을 영상으로 접할 수 있는 영상시설 등의 최신 전시기법으로 전시하여 도심에서 자연을 쉽게 느낄 수 있는 자연사의 산 교육장이다. 자연사에 관련된 순수 학술 연구와 동물, 식물과 광물·암석·화석을 채집, 보존, 전시, 연구하고 멸종 위기 생물 종의 조사와 천연기념물, 국제보호조, 특산·희귀종, 신종 등 희귀한 표본을 다수 소장 및 전시하고 있다. 귀중한 자연사 표본은 항온·항습 시설을 갖춘 최신 시설의 수장고에 보관하여 연구자료로 활용하고 있다. 또, 학생들을 위한 다양한 과학탐구실험과 자연관찰 프로그램인 자연사교실과 현장학습 교육프로그램과 특강을 운영하고 있다. 전시는 식물, 곤충, 무척추동물, 척추동물, 지구과학 코너, 디오라마, 생태코너로 구성된 상설전시와 매년 분야별로 주제를 선정하여 개최하는 기획 전시로 이루어져 있다. 지금까지 다양한 기획전시와 특별전을 개최하여 자연사의 분야별 심층 전시를 실시해 왔다. 또한, 인터넷에 자연사박물관 홈페이지와 천연기념물, 멸종위기 및 보호대상종 웹 컨텐트 개발과 사이버 자연사박물관을 개관하여 박물관 자료의 정보 서비스화에도 앞서가고 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/46/3305246_image2_1.jpg', '', 'TOURAPI', '130949', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 이화여대길 52","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"130949","contenttypeid":"14","createdtime":"20070806090000","firstimage":"https://tong.visitkorea.or.kr/cms/resource/46/3305246_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/46/3305246_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9465802534","mapy":"37.5617080471","mlevel":"6","modifiedtime":"20261016152814","sigungucode":"","tel":"","title":"이화여대 자연사박물관","zipcode":"03760","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE07","lclsSystm3":"VE070100","detail":{"contentid":"130949","contenttypeid":"14","title":"이화여대 자연사박물관","createdtime":"20070806090000","modifiedtime":"20261016152814","tel":"","telname":"","homepage":"https://cms.ewha.ac.kr","firstimage":"https://tong.visitkorea.or.kr/cms/resource/46/3305246_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/46/3305246_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE07","lclsSystm3":"VE070100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 이화여대길 52","addr2":"","zipcode":"03760","mapx":"126.9465802534","mapy":"37.5617080471","mlevel":"6","overview":"이화여자대학교 자연사박물관은 자연에 대한 학교교육과 사회교육에 이바지할 목적으로 1969년 11월 20일 국내 최초로 설립되었다. 자연사박물관은 동물, 식물, 광물, 암석, 화석의 다양한 표본들과 실제 자연 생태계를 재현해 놓은 디오라마 전시, 살아있는 동물을 관찰할 수 있는 생태 코너, 자연환경을 영상으로 접할 수 있는 영상시설 등의 최신 전시기법으로 전시하여 도심에서 자연을 쉽게 느낄 수 있는 자연사의 산 교육장이다. \n자연사에 관련된 순수 학술 연구와 동물, 식물과 광물·암석·화석을 채집, 보존, 전시, 연구하고 멸종 위기 생물 종의 조사와 천연기념물, 국제보호조, 특산·희귀종, 신종 등 희귀한 표본을 다수 소장 및 전시하고 있다. 귀중한 자연사 표본은 항온·항습 시설을 갖춘 최신 시설의 수장고에 보관하여 연구자료로 활용하고 있다. 또, 학생들을 위한 다양한 과학탐구실험과 자연관찰 프로그램인 자연사교실과 현장학습 교육프로그램과 특강을 운영하고 있다. \n전시는 식물, 곤충, 무척추동물, 척추동물, 지구과학 코너, 디오라마, 생태코너로 구성된 상설전시와 매년 분야별로 주제를 선정하여 개최하는 기획 전시로 이루어져 있다. 지금까지 다양한 기획전시와 특별전을 개최하여 자연사의 분야별 심층 전시를 실시해 왔다. 또한, 인터넷에 자연사박물관 홈페이지와 천연기념물, 멸종위기 및 보호대상종 웹 컨텐트 개발과 사이버 자연사박물관을 개관하여 박물관 자료의 정보 서비스화에도 앞서가고 있다."}}}'
