INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-129815', '이화여자대학교 박물관', '서대문구', 37.560365, 126.944659, '서울특별시 서대문구 이화여대길 52 (대현동)', '14', '이화여자대학교 박물관은 1935년 4월 6일 처음으로 개관되었다. 한국 전쟁 기간 동안에 유엔군과 외교사절단에게 한국 문화를 알리고 문화유산의 해외유출도 막고자 부산임시교사인 필승각에 박물관을 재개관하여 일반인들에게도 관람할 수 있게 하였다. 1950년대에는 김활란 박사의 개인 소장품 수백 점을 기증받았고 1960년대에는 박물관 단독 건물을 신축하여 상설 개관하고 체계적인 유물 정리를 시작하였다. 1963년 최초의 여성발굴단을 구성하여 안동 조탑동 고분을 시작으로 남한 최초의 신라 벽화고분인 순흥어숙묘, 광주 조선백자 관요지 발굴 등을 시행하여 학술적인 성과를 이루었다. 1972년부터 해마다 소장품 특별전과 전시도록을 발간하여 본격적인 박물관의 면모를 갖추게 되었다. 1990년에는 소장품의 관리와 박물관 전시, 교육 기능을 강화하기 위하여 본교 창립 100주년 기념 박물관으로 신축되어 현대적인 공간이 마련되었다. 1990년대 후반부터는 고대와 현대를 접목하는 특별전이 기획되었고 박물관의 체계적인 유물 정리와 홍보를 위한 유물 전산화 작업과 홈페이지가 운영되었다. 2005년에는 박물관이 증축되어 확대되었으며 이후 현대미술전시관이 신설되어 더욱 다양한 전시의 기획이 가능해졌다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/61/3509961_image2_1.jpg', '', 'TOURAPI', '129815', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 이화여대길 52 (대현동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"129815","contenttypeid":"14","createdtime":"20071106103139","firstimage":"https://tong.visitkorea.or.kr/cms/resource/61/3509961_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/61/3509961_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.944659","mapy":"37.560365","mlevel":"6","modifiedtime":"20260311100340","sigungucode":"","tel":"","title":"이화여자대학교 박물관","zipcode":"03760","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE07","lclsSystm3":"VE070100","detail":{"contentid":"129815","contenttypeid":"14","title":"이화여자대학교 박물관","createdtime":"20071106103139","modifiedtime":"20260311100340","tel":"","telname":"","homepage":"http://museum.ewha.ac.kr","firstimage":"https://tong.visitkorea.or.kr/cms/resource/61/3509961_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/61/3509961_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"VE","lclsSystm2":"VE07","lclsSystm3":"VE070100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 이화여대길 52 (대현동)","addr2":"","zipcode":"03760","mapx":"126.944659","mapy":"37.560365","mlevel":"6","overview":"이화여자대학교 박물관은 1935년 4월 6일 처음으로 개관되었다. 한국 전쟁 기간 동안에 유엔군과 외교사절단에게 한국 문화를 알리고 문화유산의 해외유출도 막고자 부산임시교사인 필승각에 박물관을 재개관하여 일반인들에게도 관람할 수 있게 하였다. 1950년대에는 김활란 박사의 개인 소장품 수백 점을 기증받았고 1960년대에는 박물관 단독 건물을 신축하여 상설 개관하고 체계적인 유물 정리를 시작하였다. 1963년 최초의 여성발굴단을 구성하여 안동 조탑동 고분을 시작으로 남한 최초의 신라 벽화고분인 순흥어숙묘, 광주 조선백자 관요지 발굴 등을 시행하여 학술적인 성과를 이루었다. 1972년부터 해마다 소장품 특별전과 전시도록을 발간하여 본격적인 박물관의 면모를 갖추게 되었다. 1990년에는 소장품의 관리와 박물관 전시, 교육 기능을 강화하기 위하여 본교 창립 100주년 기념 박물관으로 신축되어 현대적인 공간이 마련되었다. 1990년대 후반부터는 고대와 현대를 접목하는 특별전이 기획되었고 박물관의 체계적인 유물 정리와 홍보를 위한 유물 전산화 작업과 홈페이지가 운영되었다. 2005년에는 박물관이 증축되어 확대되었으며 이후 현대미술전시관이 신설되어 더욱 다양한 전시의 기획이 가능해졌다."}}}'
