INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-2940410', '진돈부리', '서대문구', 37.5569974331, 126.9422974721, '서울특별시 서대문구 대현동 104-36', '39', '진돈부리는 서울 신촌에 위치한 덮밥 전문점이다. 오픈 키친 형태의 아담한 공간에서 다양한 덮밥 메뉴를 선보이며, 대표 메뉴인 연어 덮밥으로 잘 알려져 있다. 신선한 연어를 푸짐하게 올린 연어 덮밥은 한정 수량으로 제공되며, 꽃 모양으로 담아낸 정갈한 비주얼이 눈길을 끈다. 이 밖에도 다양한 덮밥 메뉴를 갖추고 있어 취향에 따라 선택할 수 있으며, 새우튀김과 감자고로케 등 곁들임 메뉴도 함께 즐길 수 있다. 신촌을 찾은 이들이 간편하게 한 끼 식사를 즐기기 좋은 곳이다.', 'https://www.data.go.kr/data/15101578/openapi.do', NULL, '', 'TOURAPI', '2940410', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 대현동","addr2":"104-36","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2940410","contenttypeid":"39","createdtime":"20230103154403","firstimage":"","firstimage2":"","cpyrhtDivCd":"","mapx":"126.9422974721","mapy":"37.5569974331","mlevel":"6","modifiedtime":"20260605084251","sigungucode":"","tel":"","title":"진돈부리","zipcode":"03766","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020200","detail":{"contentid":"2940410","contenttypeid":"39","title":"진돈부리","createdtime":"20230103154403","modifiedtime":"20260605084251","tel":"","telname":"","homepage":"","firstimage":"","firstimage2":"","cpyrhtDivCd":"","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020200","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 대현동","addr2":"104-36","zipcode":"03766","mapx":"126.9422974721","mapy":"37.5569974331","mlevel":"6","overview":"진돈부리는 서울 신촌에 위치한 덮밥 전문점이다. 오픈 키친 형태의 아담한 공간에서 다양한 덮밥 메뉴를 선보이며, 대표 메뉴인 연어 덮밥으로 잘 알려져 있다. 신선한 연어를 푸짐하게 올린 연어 덮밥은 한정 수량으로 제공되며, 꽃 모양으로 담아낸 정갈한 비주얼이 눈길을 끈다. 이 밖에도 다양한 덮밥 메뉴를 갖추고 있어 취향에 따라 선택할 수 있으며, 새우튀김과 감자고로케 등 곁들임 메뉴도 함께 즐길 수 있다. 신촌을 찾은 이들이 간편하게 한 끼 식사를 즐기기 좋은 곳이다."}}}'
WHERE NOT EXISTS (SELECT 1 FROM catalog_place WHERE id = 'tourapi-2940410');

