SELECT 'tourapi-132903', '청송본관함흥냉면', '서대문구', 37.5658350001, 126.9287596527, '서울특별시 서대문구 연희맛로 6', '39', '연희동에 위치한 청송본관함흥냉면은 녹말을 압착한 면을 쓰는 함흥냉면식 냉면집이다. 주로 함경도 지방에 많이 나는 감자를 사용한다. 반죽을 해 놓았다가 20년 넘는 경력의 주방장이 즉시 면을 뽑아서 제공한다. 또한 모든 반찬은 직접 주방에서 만들고, 왕만두도 직접 손으로 빚어 제공한다. 이외에도 수육, 홍어회 등의 다양한 메뉴가 있어 현지인이 찾는 맛집으로 유명하다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/17/3567317_image2_1.jpg', '', 'TOURAPI', '132903', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희맛로 6","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"132903","contenttypeid":"39","createdtime":"20040217090000","firstimage":"https://tong.visitkorea.or.kr/cms/resource/17/3567317_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/17/3567317_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9287596527","mapy":"37.5658350001","mlevel":"6","modifiedtime":"20261012162747","sigungucode":"","tel":"","title":"청송본관함흥냉면","zipcode":"03708","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","detail":{"contentid":"132903","contenttypeid":"39","title":"청송본관함흥냉면","createdtime":"20040217090000","modifiedtime":"20261012162747","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/17/3567317_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/17/3567317_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 연희맛로 6","addr2":"","zipcode":"03708","mapx":"126.9287596527","mapy":"37.5658350001","mlevel":"6","overview":"연희동에 위치한 청송본관함흥냉면은 녹말을 압착한 면을 쓰는 함흥냉면식 냉면집이다. 주로 함경도 지방에 많이 나는 감자를 사용한다. 반죽을 해 놓았다가 20년 넘는 경력의 주방장이 즉시 면을 뽑아서 제공한다. 또한 모든 반찬은 직접 주방에서 만들고, 왕만두도 직접 손으로 빚어 제공한다. 이외에도 수육, 홍어회 등의 다양한 메뉴가 있어 현지인이 찾는 맛집으로 유명하다."}}}'
