INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-2807816', '청화원', '서대문구', 37.5574084079, 126.9375173712, '서울특별시 서대문구 명물길 10', '39', '서대문구 창천동에 위치한 청화원은 대만식 전통 우육면과 딤섬 전문점이다. 진하게 우린 소고기 국물에 부드러운 아롱사태, 결을 따라 칼로 깎듯이 쳐내 만든 우육도삭면이 대표 메뉴이며, 홍콩식 딤섬 메뉴도 인기다. 이 외에도 크림새우, 마라 두부, 유린기 등 다양한 중화요리를 맛볼 수 있다. 매장 내부는 넓은 편이라 쾌적하게 식사하기 좋다. 또한 2인석부터 단체석까지 구비되어 있어 상황에 맞게 알맞은 식사가 가능하다. 새로운 맛의 중화요리로 사람들의 발길이 끊이지 않는 곳이다. 신촌역 3번 출구 근처에 있어 접근성도 편리하다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/13/3574813_image2_1.jpg', '', 'TOURAPI', '2807816', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 명물길 10","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2807816","contenttypeid":"39","createdtime":"20220221155821","firstimage":"https://tong.visitkorea.or.kr/cms/resource/13/3574813_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/13/3574813_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9375173712","mapy":"37.5574084079","mlevel":"6","modifiedtime":"20260724090144","sigungucode":"","tel":"","title":"청화원","zipcode":"03777","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020100","detail":{"contentid":"2807816","contenttypeid":"39","title":"청화원","createdtime":"20220221155821","modifiedtime":"20260724090144","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/13/3574813_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/13/3574813_image3_1.jpg","cpyrhtDivCd":"Type3","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD02","lclsSystm3":"FD020100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 명물길 10","addr2":"","zipcode":"03777","mapx":"126.9375173712","mapy":"37.5574084079","mlevel":"6","overview":"서대문구 창천동에 위치한 청화원은 대만식 전통 우육면과 딤섬 전문점이다. 진하게 우린 소고기 국물에 부드러운 아롱사태, 결을 따라 칼로 깎듯이 쳐내 만든 우육도삭면이 대표 메뉴이며, 홍콩식 딤섬 메뉴도 인기다. 이 외에도 크림새우, 마라 두부, 유린기 등 다양한 중화요리를 맛볼 수 있다. 매장 내부는 넓은 편이라 쾌적하게 식사하기 좋다. 또한 2인석부터 단체석까지 구비되어 있어 상황에 맞게 알맞은 식사가 가능하다. 새로운 맛의 중화요리로 사람들의 발길이 끊이지 않는 곳이다. 신촌역 3번 출구 근처에 있어 접근성도 편리하다."}}}'
