SELECT 'tourapi-1292674', '춘천집닭갈비막국수', '서대문구', 37.5570462556, 126.9360751561, '서울특별시 서대문구 연세로5가길 1', '39', '서울 서대문구에 위치한 춘천집 닭갈비막국수는 일대에서 유명한 철판 닭갈비 전문점이다. 대표 메뉴로는 치즈 닭갈비이며 달짝지근한 닭갈비에 부드러운 치즈를 곁들여 먹는다. 이뿐만 아니라 뼈 없는 닭갈비, 매운 닭갈비 등도 취급하여 기호에 맞게 선택할 수 있다. 쫄면 등이 포함된 모둠 사리를 추가하면 골라 먹는 재미도 있다. 쟁반국수와 막국수 메뉴도 준비되어 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', NULL, '', 'TOURAPI', '1292674', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연세로5가길 1","addr2":"","areacode":"1","cat1":"A05","cat2":"A0502","cat3":"A05020100","contentid":"1292674","contenttypeid":"39","createdtime":"20110531193504","firstimage":"","firstimage2":"","cpyrhtDivCd":"","mapx":"126.9360751561","mapy":"37.5570462556","mlevel":"6","modifiedtime":"20251212164315","sigungucode":"14","tel":"","title":"춘천집닭갈비막국수","zipcode":"03789","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","detail":{"contentid":"1292674","contenttypeid":"39","title":"춘천집닭갈비막국수","createdtime":"20110531193504","modifiedtime":"20251212164315","tel":"","telname":"","homepage":"","firstimage":"","firstimage2":"","cpyrhtDivCd":"","areacode":"1","sigungucode":"14","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD01","lclsSystm3":"FD010100","cat1":"A05","cat2":"A0502","cat3":"A05020100","addr1":"서울특별시 서대문구 연세로5가길 1","addr2":"","zipcode":"03789","mapx":"126.9360751561","mapy":"37.5570462556","mlevel":"6","overview":"서울 서대문구에 위치한 춘천집 닭