SELECT 'tourapi-2996477', '카페 폭포', '서대문구', 37.581294844, 126.9370197988, '서울특별시 서대문구 연희로 262-24 (홍은동)', '39', '카페 폭포는 서울시 서대문구 홍은동에 위치한 전망 카페로, 홍제천 인공폭포를 가까이에서 감상할 수 있는 이색 공간이다. 아메리카노, 바닐라라떼, 밀크티, 에이드 등 다양한 음료를 판매하며, 실내와 야외 어디에서나 폭포를 바라볼 수 있도록 좌석이 마련되어 있다. 자연 절벽을 따라 쏟아지는 듯한 웅장한 인공폭포는 도심 속에서도 시원한 풍경을 선사한다. 서대문구에서 운영하는 공공 카페로, 운영 수익금은 지역 대학생 장학금으로 사용되어 의미를 더한다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/83/3570483_image2_1.jpg', '', 'TOURAPI', '2996477', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희로 262-24 (홍은동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2996477","contenttypeid":"39","createdtime":"20230727174125","firstimage":"https://tong.visitkorea.or.kr/cms/resource/83/3570483_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/83/3570483_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9370197988","mapy":"37.5812948440","mlevel":"6","modifiedtime":"20260803183626","sigungucode":"","tel":"","title":"카페 폭포","zipcode":"03653","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD05","lclsSystm3":"FD050100","detail":{"contentid":"2996477","contenttypeid":"39","title":"카페 폭포","createdtime":"20230727174125","modifiedtime":"20260803183626","tel":"","telname":"","homepage":"","firstimage":"https://tong.visitkorea.or.kr/cms/resource/83/3570483_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/83/3570483_