SELECT 'tourapi-4092567', '코코리컬러 연희본점', '서대문구', 37.5742302252, 126.9352330782, '서울특별시 서대문구 연희로 193-3 (연희동)', '12', '코코리컬러 연희본점은 개인의 피부색과 얼굴·체형 특성을 바탕으로 어울리는 색과 스타일을 분석하는 체험형 K-뷰티 공간이다. 피부 측색과 컬러 드레이핑을 통해 명도·채도·색상 경향을 살피고, 립·액세서리·헤어·메이크업 컬러 등 일상에서 활용할 수 있는 결과를 제공하는 곳이다. 기본 퍼스널컬러 프로그램뿐만 아니라 얼굴·체형 분석, 메이크업과 이목구비 분석, 퍼스널 메이크업 등을 예약제로 운영한다. 프로그램은 한국어·영어·중국어·일본어 증 선택할 수 있어 내국인과 외국인 모두 이용 가능하며, 상담 결과를 패션·뷰티 제품 선택에 활용할 수 있도록 개인별 컬러와 디자인 방향을 안내한다. 쇼핑과 관광 일정에 연계하기 좋은 체험 장소이며, 예약은 공식 홈페이지에서 프로그램과 날짜를 선택하여 가능하다. 연희본점뿐만 아니라 강남점, 명동점, 홍대점도 위치해 있어 접근성이 좋고 편리하다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/71/4092571_image2_1.jpg', '', 'TOURAPI', '4092567', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희로 193-3 (연희동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"4092567","contenttypeid":"12","createdtime":"20260727103602","firstimage":"https://tong.visitkorea.or.kr/cms/resource/71/4092571_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/71/4092571_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.9352330782","mapy":"37.5742302252","mlevel":"","modifiedtime":"20260727104353","sigungucode":"","tel":"","title":"코코리컬러 연희본점","zipcode":"03697","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"EX","lclsSystm2":"EX07","lclsSystm3":"EX070200","detail":{"contentid":"4092567","contenttypeid":"12","title":"코코리컬러 연희본점","createdtime":"20260727103602","modifiedtime":"2026