SELECT 'tourapi-2751441', '포방터시장', '서대문구', 37.5987727707, 126.9497172483, '서울특별시 서대문구 포방터2길 11 (홍은동)', '38', '포방터시장은 임진왜란 이후 도성을 지키기 위해 설치한 포 훈련을 했던 곳이자 한국전쟁 당시 서울을 방어했던 곳인 포방터에 형성되어 오늘날 포방터장으로 불리게 됐다. 북한산과 인왕산으로 둘러싸여 있으며, 90여 개의 가게가 입점해 있는 작은 시장이다. 영화와 드라마 촬영지로 이용되고 있으며, 시장 내 음식점이 TV 프로그램 으로 소개되면서부터 시장을 찾는 사람들도 꾸준히 증가하고 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/23/4101123_image2_1.jpg', '', 'TOURAPI', '2751441', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 포방터2길 11 (홍은동)","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2751441","contenttypeid":"38","createdtime":"20210930002217","firstimage":"https://tong.visitkorea.or.kr/cms/resource/23/4101123_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/23/4101123_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9497172483","mapy":"37.5987727707","mlevel":"6","modifiedtime":"20260819153837","sigungucode":"","tel":"","title":"포방터시장","zipcode":"03607","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"SH","lclsSystm2":"SH06","lclsSystm3":"SH060200","detail":{"contentid":"2751441","contenttypeid":"38","title":"포방터시장","createdtime":"20210930002217","modifiedtime":"20260819153837","tel":"","telname":"","homepage":"https://blog.naver.com/pobangq","firstimage":"https://tong.visitkorea.or.kr/cms/resource/23/4101123_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/23/4101123_image3_