SELECT 'tourapi-2839897', '피터팬1978', '서대문구', 37.5693707324, 126.931664824, '서울특별시 서대문구 증가로 10', '39', '1978년부터 연희동 주민들의 사랑을 받아온 30년이 넘는 전통을 지닌 빵집이다. 중소벤처기업부의 공식 인증을 통해 우수성을 인정받았고 각종 방송에도 소개되었다. 독특한 모양과 이름을 가진 아기 궁댕이 빵이 메인 메뉴다. 그 외에도 장발장이 훔친 빵, 깜빠뉴, 통호밀식빵, 소금빵, 펌퍼니클 등 다양한 빵을 즐길 수 있다. 커피나 음료를 함께 구매하면 2층에 있는 카페도 이용할 수 있다. 연희대공원이 가까워 산책하기에 좋다.', 'https://www.data.go.kr/data/15101578/openapi.do', NULL, '', 'TOURAPI', '2839897', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 증가로 10","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2839897","contenttypeid":"39","createdtime":"20220819143149","firstimage":"","firstimage2":"","cpyrhtDivCd":"","mapx":"126.9316648240","mapy":"37.5693707324","mlevel":"6","modifiedtime":"20261104140120","sigungucode":"","tel":"","title":"피터팬1978","zipcode":"03698","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD05","lclsSystm3":"FD050100","detail":{"contentid":"2839897","contenttypeid":"39","title":"피터팬1978","createdtime":"20220819143149","modifiedtime":"20261104140120","tel":"","telname":"","homepage":"","firstimage":"","firstimage2":"","cpyrhtDivCd":"","areacode":"","sigungucode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"FD","lclsSystm2":"FD05","lclsSystm3":"FD050100","cat1":"","cat2":"","cat3":"","addr1":"서울특별시 서대문구 증가로 10","addr2":"","zipcode":"03698","mapx":"126.9316648240","mapy":"37.5693707324","mlevel":"6","overview":"1978년부터 연희동 주민들의 사랑을 받아온 30년이 넘는 전통을 지닌 빵집이다. 중소벤처기업부의 공식 인증을 통해 우수성을 인정받았고 각종 방송에도 소개되었다. 독특한 모양과 이름을 가진 아기 궁댕이 빵이 메인 메뉴다. 그 외에도 장발장이 훔친 빵, 깜빠뉴, 통호밀식빵, 소금빵, 펌퍼니클 등 다양한 빵을 즐길 수 있다. 커피나 음료를 함께 구매하면 2층에 있는 카페도 이용할 수 있다. 연희대공원이 가까워 산책하기에 좋다."}}}'
