SELECT 'tourapi-1837036', '해병대 104고지 전적비', '서대문구', 37.5679, 126.926, '서울특별시 서대문구 연희동 산100-1', '12', '서울 서대문구 연희동에 서울 서쪽 관문인 104고지 탈환 작전 중 전사한 해병대 장병들을 추모하기 위해 해병대 사령부에서 1982년 9월 28일 이 비를 세웠다. 인천상륙작전의 성공으로 해병은 서울 탈환을 목적으로 계속 진격하던 중 1950년 9월 21일 서울의 서쪽 관문인 104고지에서 치열한 전투가 벌어졌다. 104고지 점령은 서울시민 구출의 선도를 여는 계기가 되기 때문에 해병은 결사적 반격을 가했다. 그러나 북한군은 완강히 저항했고 3주간의 끝없는 혈전으로 한 개 중대 중 26명만 생존하는 처절한 혈전 끝에 고지를 탈환했다. 적은 104고지 일대를 요새화하여 난공불락을 호언하며 서울 사수의 최후방어선으로 확보 중에 있었으나 인천상륙작전을 성공한 한미해병대는 공격을 계속했다. 해병 제1대대가 104고지를 조기에 탈취 역사적인 수도탈환작전에 결정적인 기여를 함으로써 상승해병의 위용을 만천하에 떨쳤다. (출처 : 국가보훈부)', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/96/3515096_image2_1.jpg', '', 'TOURAPI', '1837036', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희동","addr2":"산100-1","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"1837036","contenttypeid":"12","createdtime":"20130812194350","firstimage":"https://tong.visitkorea.or.kr/cms/resource/96/3515096_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/96/3515096_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.926","mapy":"37.5679","mlevel":"6","modifiedtime":"20260312090840","sigungucode":"","tel":"","title":"해병대 104고지 전적비","zipcode":"03706","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"HS","lclsSystm2":"HS02","lclsSystm3":"HS020100","detail":{"contentid":"1837036","contenttypeid":"12","title":"해병대 104고지 전적비","createdtime":"20130812194350","modifiedtime":