SELECT 'falls', '홍제천인공폭포', '서대문구', 37.5792603445, 126.9362995081, '서울특별시 서대문구 연희로 248 (연희동)', '12', '홍제천인공폭포는 도심 속 오아시스와 같은 곳이다. 25m 높이의 시원한 인공폭포가 쏟아져 내리는 장관은 더위를 식히고 일상의 피로를 잊게 해주는 멋진 풍경을 선사한다. 폭포 주변에는 산책로, 벤치, 카페 등 다양한 편의시설이 마련되어 있어 여유로운 시간을 보낼 수 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'http://tong.visitkorea.or.kr/cms/resource/45/3452745_image2_1.jpg', '', 'TOURAPI', '3452906', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희로 248 (연희동)","addr2":"","areacode":"1","cat1":"A01","cat2":"A0101","cat3":"A01010500","contentid":"3452906","contenttypeid":"12","createdtime":"20241219152851","firstimage":"http://tong.visitkorea.or.kr/cms/resource/45/3452745_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/45/3452745_image3_1.jpg","cpyrhtDivCd":"Type1","mapx":"126.9362995081","mapy":"37.5792603445","mlevel":"6","modifiedtime":"20251030143945","sigungucode":"14","tel":"","title":"홍제천인공폭포","zipcode":"03718","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"NA","lclsSystm2":"NA05","lclsSystm3":"NA050100","detail":{"contentid":"3452906","contenttypeid":"12","title":"홍제천인공폭포","createdtime":"20241219152851","modifiedtime":"20251030143945","tel":"","telname":"","homepage":"https://www.sdm.go.kr/culture/index.do","firstimage":"http://tong.visitkorea.or.kr/cms/resource/45/3452745_image2_1.jpg","firstimage2":"http://tong.visitkorea.or.kr/cms/resource/45/3452745_image3_1.jpg","cpyrhtDivCd":"Type1","areacode":"1","sigungucode":"14","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"NA","lclsSystm2":"NA05","lclsSystm3":"NA050100","cat1":"A01","cat2":"A0101","cat3":"A01010500","addr1":"서울특별시 서대문구 연희로 248 (연희동)","addr2":"","zipcode":"03718","mapx":"126.9362995081","mapy":"37.5792603445","mlevel":"6","overview":"홍제천인공폭포는 도심 속 오아시스와 같은 곳이다. 25m 높이의 시원한 인공폭포가 쏟아져 내리는 장관은 더위를 식히고 일상의 피로를 잊게 해주는 멋진 풍경을 선사한다. 폭포 주변에는 산책로, 벤치, 카페 등 다양한 편의시설이 마련되어 있어 여유로운 시간을 보낼 수 있다."}}}'
