INSERT INTO catalog_place (id, name, district, lat, lon, address, content_type_id, info, src, image_url, mood, source_name, source_id, source_json)
SELECT 'tourapi-2783698', '홍제폭포', '서대문구', 37.580697, 126.937621, '서울특별시 서대문구 연희동 170-181', '12', '서울 서대문구에 있는 홍제폭포는 홍제천을 따라 조성된 인공폭포다. 2011년 조성되어 높이 25m, 폭 60m에 달한다. 서대문 홍제폭포는 인공폭포라는 것이 믿기지 않을 정도로 자연과 잘 어우러져 있다. 계절 변화에 따라 청량감을 주는 폭포 물줄기로, 장관을 선사하는 거대한 빙벽에 봄꽃 및 가을 단풍과 어우러진 풍광으로 많은 시민의 발길이 이어지는 곳이다. 이곳에는 폭포뿐만 아니라 다양한 쉼터가 조성되어 시민들의 휴식처가 되어 준다. 폭포 건너편에는 수변 카페와 야외 테라스, 작은 도서관을 조성해 많은 즐길거리를 갖추고 있다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/00/3498000_image2_1.jpg', '', 'TOURAPI', '2783698', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 연희동 170-181","addr2":"","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"2783698","contenttypeid":"12","createdtime":"20211130221310","firstimage":"https://tong.visitkorea.or.kr/cms/resource/00/3498000_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/00/3498000_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.937621","mapy":"37.580697","mlevel":"6","modifiedtime":"20260311100340","sigungucode":"","tel":"","title":"홍제폭포","zipcode":"","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"NA","lclsSystm2":"NA01","lclsSystm3":"NA010300","detail":{"contentid":"2783698","contenttypeid":"12","title":"홍제폭포","createdtime":"20211130221310","modifiedtime":"20260311100340","tel":"","telname":"","homepage":"https://korean.visitseoul.net/","firstimage":"https://tong.visitkorea.or.kr/cms/resource/00/3498000_image2_1.jpg","firstimage2":"https://to