SELECT 'tourapi-1895366', '1919 서대문, 그날의 함성', '서대문구', 37.574618389407945, 126.95732840673385, '서울특별시 서대문구 통일로 251 (현저동) 서대문독립공원, 서대문형무소역사관, 감리교신학대학교 웨슬리채플관', '15', '제107주년 3.1절을 맞이하여 ''1919 서대문, 그날의 함성''이 2월 28일부터 3월 1일까지 서대문독립공원, 서대문형무소역사관, 감리교신학대학교 웨슬리채플관에서 열린다. 전 국민이 참여할 수 있는 기념행사를 개최함으로써 애국선열들이 추구한 자유와 평화의 가치를 공유한다. 서대문구의 역사적 명소에서 기념식과 만세운동 행진, 다양한 체험 프로그램이 운영되어 서대문독립공원 일대가 다시한번 독립운동의 성지로 거듭난다.', 'https://www.data.go.kr/data/15101578/openapi.do', 'https://tong.visitkorea.or.kr/cms/resource/99/4013399_image2_1.jpg', '', 'TOURAPI', '1895366', '{"metadata":{"file":"seodaemun.json","source":"한국관광공사 TourAPI 국문 관광정보 서비스","endpoint":"https://apis.data.go.kr/B551011/KorService2/areaBasedList2","sourceDocumentation":"https://www.data.go.kr/data/15101578/openapi.do","fetchedAt":"2026-11-05T17:51:47.7920152+00:00","region":{"name":"서울특별시","lDongRegnCd":"11","district":"서대문구","lDongSignguCd":"410"},"contentTypeFilter":null,"totalCount":161,"count":161,"detailEndpoint":"https://apis.data.go.kr/B551011/KorService2/detailCommon2","detailCount":161,"completedAt":"2026-11-05T17:52:06.8425309+00:00"},"item":{"addr1":"서울특별시 서대문구 통일로 251 (현저동)","addr2":"서대문독립공원, 서대문형무소역사관, 감리교신학대학교 웨슬리채플관","areacode":"","cat1":"","cat2":"","cat3":"","contentid":"1895366","contenttypeid":"15","createdtime":"20140217230217","firstimage":"https://tong.visitkorea.or.kr/cms/resource/99/4013399_image2_1.jpg","firstimage2":"https://tong.visitkorea.or.kr/cms/resource/99/4013399_image3_1.jpg","cpyrhtDivCd":"Type3","mapx":"126.95732840673385","mapy":"37.574618389407945","mlevel":"6","modifiedtime":"20260212085932","sigungucode":"","tel":"02-330-1410","title":"1919 서대문, 그날의 함성","zipcode":"03732","lDongRegnCd":"11","lDongSignguCd":"410","lclsSystm1":"EV","lclsSystm2":"EV01","lclsSystm3":"EV010200","detail":{"contentid":"1895366","contenttypeid":"15","title":"1919 서대문, 그날의 함성","createdtime":"20140217230217","modifiedtime":"20260212085932","tel":"02-330-1410","telname":"서대문구/서대문구도시관리공단","homepage":"https://www.s